import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoEqualCol from "../../core/TableTwoEqualCol.tsx";
import {
  ifOne,
  ifTwo,
  ifThree,
  ifFour,
  forOne,
  forTwo,
  eachOne,
  eachTwo,
  eachThree,
  eachFour,
  eachFive,
  eachSix,
  whileOne,
  whileTwo,
} from "./ScssConstPre.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function ExpressionsRU({ searchTerm }: IMethodsProps) {
  const scssIfData = [
    {
      title: "Условные выражения @if",
      category: "SCSS",
      textForSearch: "@if, @else if, @else.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Директива @if принимает выражение SassScript и использует стили,
                вложенные в нее, в случае, если выражение возвращает любое
                значение, кроме false или null:
              </p>
            }
          />
          <TableTwoEqualCol
            title={
              <p>
                <pre>
                  <code>{ifOne}</code>
                </pre>
              </p>
            }
            text={
              <p>
                <pre>
                  <code>{ifTwo}</code>
                </pre>
              </p>
            }
          />
          <TableOneCol
            text={
              <p>
                После выражения @if может следовать несколько выражений @else if
                и одно выражение @else. Если выражение @if вернет false, то
                будут производиться попытки вычисления выражений @else if, пока
                одно из них не вернет истину или до достижения выражения @else.
              </p>
            }
          />
          <TableTwoEqualCol
            title={
              <p>
                <pre>
                  <code>{ifThree}</code>
                </pre>
              </p>
            }
            text={
              <p>
                <pre>
                  <code>{ifFour}</code>
                </pre>
              </p>
            }
          />
        </>
      ),
    },
  ];

  const scssForData = [
    {
      title: "Цикл @for",
      category: "SCSS",
      textForSearch: "@for.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Директива @for выводит набор стилей заданное число раз. Для
                каждого повторения используется переменная-счетчик для изменения
                вывода.
                <br />
                Директива имеет две формы: `@for $var from начало through конец`
                и `@for $var from начало to конец`. Обратите внимание на разницу
                в словах through и to.
                <br />
                `$var` может быть любым именем переменной, таким как `$i`;
                `начало` и `конец` - выражения SassScript, которые должны
                возвращать целые числа. Если `начало` больше, чем `конец`,
                счетчик будет уменьшаться, вместо того чтобы расти.
                <br />
                Выражение @for устанавливает переменную `$var` в каждое
                следующее значение в заданном диапазоне и каждый раз выводит
                вложенные стили, используя очередное значение переменной `$var`.
                Форма `from ... through` включает значения `начало` и `конец`, а
                форма `from ... to` не включает значение `конец`.
              </p>
            }
          />
          <TableTwoEqualCol
            title={
              <p>
                <pre>
                  <code>{forOne}</code>
                </pre>
              </p>
            }
            text={
              <p>
                <pre>
                  <code>{forTwo}</code>
                </pre>
              </p>
            }
          />
        </>
      ),
    },
  ];

  const scssEachData = [
    {
      title: "Цикл @each",
      category: "SCSS",
      textForSearch: "@each.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Директива @each обычно имеет вид `@each $var in список` или
                карту значений. `$var` может быть любой переменной, такой как
                `$length` или `$name`, а список или карта значений — это
                выражение SassScript, возвращающее список или карту значений.
                <br />
                Директива @each устанавливает `$var` в каждое из значений списка
                или карты и выводит в ней стили, используя соответствующее
                значение `$var`. Например:
              </p>
            }
          />
          <TableTwoEqualCol
            title={
              <p>
                <pre>
                  <code>{eachOne}</code>
                </pre>
              </p>
            }
            text={
              <p>
                <pre>
                  <code>{eachTwo}</code>
                </pre>
              </p>
            }
          />
          <TableOneCol
            text={
              <p>
                Директива @each также может использовать несколько переменных по
                такому принципу: `@each $var1, $var2, ... список`. Если список —
                это список списков, значение каждого элемента внутреннего списка
                будет присвоено соответствующей переменной. Например:
              </p>
            }
          />
          <TableTwoEqualCol
            title={
              <p>
                <pre>
                  <code>{eachThree}</code>
                </pre>
              </p>
            }
            text={
              <p>
                <pre>
                  <code>{eachFour}</code>
                </pre>
              </p>
            }
          />
          <TableOneCol
            text={
              <p>
                Поскольку карты обрабатываются как списки или пары значений,
                множественное присвоение с ними также работает. Например:
              </p>
            }
          />
          <TableTwoEqualCol
            title={
              <p>
                <pre>
                  <code>{eachFive}</code>
                </pre>
              </p>
            }
            text={
              <p>
                <pre>
                  <code>{eachSix}</code>
                </pre>
              </p>
            }
          />
        </>
      ),
    },
  ];

  const scssWhileData = [
    {
      title: "Цикл @while",
      category: "SCSS",
      textForSearch: "@while.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Директива @while принимает выражение SassScript и циклически
                выводит вложенные в нее стили, пока выражение вычисляется как
                true. Она может быть использована для создания более сложных
                циклов, чем тех, для которых подходит @for, хотя она бывает
                нужна довольно редко. Например:
              </p>
            }
          />
          <TableTwoEqualCol
            title={
              <p>
                <pre>
                  <code>{whileOne}</code>
                </pre>
              </p>
            }
            text={
              <p>
                <pre>
                  <code>{whileTwo}</code>
                </pre>
              </p>
            }
          />
        </>
      ),
    },
  ];

  const filteredScssIfData = scssIfData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredScssForData = scssForData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredScssEachData = scssEachData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredScssWhileData = scssWhileData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredScssIfData.length > 0 && (
        <Table id="scss_if">
          <TableBody>
            <TableOneCol text={<h2>Выражения.</h2>} />
            <TableOneCol text={<h3>@if</h3>} />
            {filteredScssIfData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}

      {filteredScssForData.length > 0 && (
        <Table id="scss_for">
          <TableBody>
            <TableOneCol text={<h3>@for</h3>} />
            {filteredScssForData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}

      {filteredScssEachData.length > 0 && (
        <Table id="scss_each">
          <TableBody>
            <TableOneCol text={<h3>@each</h3>} />
            {filteredScssEachData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}

      {filteredScssWhileData.length > 0 && (
        <Table id="scss_while">
          <TableBody>
            <TableOneCol text={<h3>@while</h3>} />
            {filteredScssWhileData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
