import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function ScssTitleRU({ searchTerm }: IMethodsProps) {
  const scssTitleData = [
    {
      title: "Изучение SCSS",
      category: "SCSS",
      textForSearch:
        "Изучение SCSS, Sass, CSS, переменные, вложенности, миксины, наследование.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Sass позволяет использовать функции, недоступные в самом CSS,
                например, переменные, вложенности, миксины, наследование и
                другие приятные вещи, возвращающие удобство написания CSS.
              </p>
            }
          />
        </>
      ),
    },
  ];

  const filteredScssTitleData = scssTitleData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredScssTitleData.length > 0 && (
        <Table id="scss_title">
          <TableBody>
            <TableOneCol text={<h1>Изучение SCSS.</h1>} />
            {filteredScssTitleData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
