import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function ScriptingRU({ searchTerm }: IMethodsProps) {
  const scriptingData = [
    {
      title: "Скриптинг",
      category: "HTML",
      textForSearch: "Скриптинг, <canvas>, <noscript>, <script>.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Содержание мультимедийных HTML включает в себя другие материалы,
                даже если они не всегда легко взаимодействуют.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "<canvas>",
      category: "HTML",
      textForSearch: "<canvas>, графика, скрипты, JavaScript, анимации.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;canvas&gt; &lt;/canvas&gt;</h3>}
          text={
            <p>
              Элемент может быть использован для отрисовки графики через скрипты
              (обычно используется **JavaScript**). Например, его можно
              использовать для отрисовки графиков, делать композиции фото или
              даже выполнять анимации. Вы можете (и должны) дать альтернативное
              содержание внутри блока &lt;canvas&gt;. Этот контент будет
              рендерится в старых браузерах, которые не поддерживают
              &lt;canvas&gt; и в браузерах с отключённым JavaScript.
            </p>
          }
        />
      ),
    },
    {
      title: "<noscript>",
      category: "HTML",
      textForSearch: "<noscript>, без JavaScript, отключенный JavaScript.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;noscript&gt; &lt;/noscript&gt;</h3>}
          text={
            <p>
              Определяет секцию HTML кода, которая будет вставлена, если в
              браузере пользователя нет либо отключена поддержка JavaScript.
            </p>
          }
        />
      ),
    },
    {
      title: "<script>",
      category: "HTML",
      textForSearch: "<script>, JavaScript, исполняемый код, скрипт.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;script&gt; &lt;/script&gt;</h3>}
          text={
            <p>
              Используется для встраивания или подключения исполняемого
              **JavaScript** кода.
            </p>
          }
        />
      ),
    },
  ];

  const filteredScriptingData = scriptingData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredScriptingData.length > 0 && (
        <Table id="html_scripting">
          <TableBody>
            {" "}
            <TableOneCol text={<h2>Скриптинг.</h2>} />
            {filteredScriptingData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
