import { Link } from "react-router-dom";
import Container from "@mui/material/Container";
import ButtonLanguages from "../core/ButtonLanguages.tsx";
import "./menuComponent.scss";
import { IMenuComponentProps } from "../types/interface.ts";

function MenuComponent({ onClose, ...props }: IMenuComponentProps) {
  return (
    <Container style={{ width: "100%", maxWidth: "none" }}>
      <div className="menu-container">
        <div>
          <ButtonLanguages
            className={props.classLangUA}
            to={props.toUA}
            titleLanguage={props.titleLangUA}
          />
          <ButtonLanguages
            className={props.classLangRU}
            to={props.toRU}
            titleLanguage={props.titleLangRU}
          />
        </div>
        <Link className="link-page" to={props.toHome} onClick={onClose}>
          {props.nameHome}
        </Link>
        <Link className="link-page" to={props.toHtml} onClick={onClose}>
          {props.nameHtml}
        </Link>
        <Link className="link-page" to={props.toCss} onClick={onClose}>
          {props.nameCss}
        </Link>
        <Link className="link-page" to={props.toScss} onClick={onClose}>
          {props.nameScss}
        </Link>
        <Link className="link-page" to={props.toJS} onClick={onClose}>
          {props.nameJS}
        </Link>
        <Link className="link-page" to={props.toDom} onClick={onClose}>
          {props.nameDom}
        </Link>
        <Link className="link-page" to={props.toBom} onClick={onClose}>
          {props.nameBom}
        </Link>
        <Link className="link-page" to={props.toHttp} onClick={onClose}>
          {props.nameHttp}
        </Link>
        <Link className="link-page" to={props.toReact} onClick={onClose}>
          {props.nameReact}
        </Link>
        <Link className="link-page" to={props.toRedux} onClick={onClose}>
          {props.nameRedux}
        </Link>
        <Link className="link-page" to={props.toTS} onClick={onClose}>
          {props.nameTS}
        </Link>
        <Link className="link-page" to={props.toNext} onClick={onClose}>
          {props.nameNext}
        </Link>
      </div>
    </Container>
  );
}

export default MenuComponent;
