import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import ButtonExampleWithBtn from "../../core/ButtonExampleWithBtn.tsx";
import { changeAttribute } from "./DomConstPre.tsx";
import { changeAttributeFn } from "./DomFunc.js";
import { IMethodsProps } from "../../types/interface.ts";

export default function AttributesClassUA({ searchTerm }: IMethodsProps) {
  const tableAttribute = [
    {
      title: ".hasAttribute",
      category: "DOM",
      textForSearch: "Перевірка наявності атрибута.",
      jsx: (
        <TableTwoCol
          title={<h3>.hasAttribute</h3>}
          text={
            <p>
              Перевіряє наявність атрибуту. <br />
              <code>element.hasAttribute(name)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".getAttribute",
      category: "DOM",
      textForSearch: "Отримання значення атрибута.",
      jsx: (
        <TableTwoCol
          title={<h3>.getAttribute</h3>}
          text={
            <p>
              Отримує значення атрибута. <br />
              <code>element.getAttribute(name)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".setAttribute",
      category: "DOM",
      textForSearch: "Встановлення значення атрибута.",
      jsx: (
        <TableTwoCol
          title={<h3>.setAttribute</h3>}
          text={
            <p>
              Встановлює атрибут. <br />
              <code>element.setAttribute(ім'я, значення)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".removeAttribute",
      category: "DOM",
      textForSearch: "Видалення атрибута.",
      jsx: (
        <TableTwoCol
          title={<h3>.removeAttribute</h3>}
          text={
            <p>
              Видаляє атрибут.
              <br />
              <code>element.removeAttribute(name)</code>
            </p>
          }
        />
      ),
    },
    {
      title: "Приклад використання атрибутів",
      category: "DOM",
      textForSearch: "Приклад використання DOM атрибутів у JavaScript.",
      jsx: (
        <ButtonExampleWithBtn
          titleButtonExample={"Приклад використання"}
          title={
            <p id="formated-text">
              Є тег &lt;p id="attribute-text"&gt;&lt;/p&gt;
              <br />
              Перевіримо, чи є в теги id, виведемо id і додамо class="text"
              <br />
              <br />
              <span id="attribute-text">Початковий текст.</span>
            </p>
          }
          text={
            <pre>
              <code>{changeAttribute}</code>
            </pre>
          }
          onClick={changeAttributeFn}
        />
      ),
    },
  ];

  const tableData = [
    {
      title: ".className",
      category: "DOM",
      textForSearch: "Отримання/встановлення значення атрибута class.",
      jsx: (
        <TableTwoCol
          title={<h3>.className</h3>}
          text={
            <p>
              Відповідає за значення атрибута <b>class</b> елемента.
              <br />
              <code>element.className</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".classList",
      category: "DOM",
      textForSearch: "Псевдомасив з усіма класами елемента.",
      jsx: (
        <TableTwoCol
          title={<h3>.classList</h3>}
          text={
            <p>
              Повертає псевдомасив DOMTokenList, що містить усі класи елемента.{" "}
              <br />
              <code>element.classList</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".classList.contains",
      category: "DOM",
      textForSearch: "Перевірка наявності класу.",
      jsx: (
        <TableTwoCol
          title={<h3>.classList.contains</h3>}
          text={
            <p>
              Повертає <b>true/false</b>, залежно від того, чи є у елемента
              клас. <br />
              <code>element.classList.contains("class")</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".classList.add",
      category: "DOM",
      textForSearch: "Додавання класу.",
      jsx: (
        <TableTwoCol
          title={<h3>.classList.add</h3>}
          text={
            <p>
              Додає клас. <br />
              <code>element.classList.add("class")</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".classList.remove",
      category: "DOM",
      textForSearch: "Видалення класу.",
      jsx: (
        <TableTwoCol
          title={<h3>.classList.remove</h3>}
          text={
            <p>
              Видаляє клас. <br />
              <code>element.classList.remove("class")</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".classList.toggle",
      category: "DOM",
      textForSearch: "Додавання/видалення класу за умовою.",
      jsx: (
        <TableTwoCol
          title={<h3>.classList.toggle</h3>}
          text={
            <p>
              Якщо класу немає, додає його, якщо є – видаляє.
              <br />
              <code>element.classList.toggle("class")</code>
            </p>
          }
        />
      ),
    },
  ];

  const filteredAttribute = tableAttribute.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredData = tableData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredAttribute.length > 0 && (
        <Table id="dom_attribute">
          <TableBody>
            <TableOneCol text={<h3>Атрибути.</h3>} />
            <TableOneCol
              text={
                <p>
                  За допомогою нестандартних атрибутів можна прив'язати до
                  елемента дані, доступні у JavaScript. Це робиться за допомогою
                  атрибутів з назвами, що починаються на <b>data-</b>
                </p>
              }
            />
            {filteredAttribute.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}

      {filteredData.length > 0 && (
        <Table id="dom_classes">
          <TableBody>
            <TableOneCol text={<h3>Класи.</h3>} />
            {filteredData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
