import React, { useState, useEffect, useRef } from "react";
import Container from "@mui/material/Container";
import TableContainer from "@mui/material/TableContainer";
import Button from "@mui/material/IconButton";
import Arrow from "../../core/Arrow";
import MenuDom from "./MenuDom.tsx";
import "./dom.scss";
import DomModelUA from "./DomModelUA.tsx";
import DomFindElementsUA from "./DomFindElementsUA.tsx";
import ChangePropertiesUA from "./ChangePropertiesUA.tsx";
import AttributesClassUA from "./AttributesClassUA.tsx";
import CreatingNodesUA from "./CreatingNodesUA.tsx";
import ElementsUA from "./ElementsUA.tsx";
import ListenerUA from "./ListenerUA.tsx";
import EventUA from "./EventUA.tsx";
import AppBar from "../AppBar.tsx";

export default function DomUA() {
  const [isMenuInfoOpen, setIsMenuInfoOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const menuRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  const handleMenuInfoOpen = () => {
    setIsMenuInfoOpen(!isMenuInfoOpen);
  };

  const handleMenuInfoClose = () => {
    setIsMenuInfoOpen(false);
  };

  useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      if (
        isMenuInfoOpen &&
        menuRef.current &&
        !menuRef.current.contains(event.target as Node) &&
        buttonRef.current &&
        !buttonRef.current.contains(event.target as Node)
      ) {
        setIsMenuInfoOpen(false);
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);

    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
    };
  }, [isMenuInfoOpen]);

  const handleSearch = (term) => {
    setSearchTerm(term);
  };

  return (
    <>
      <AppBar
        onSearch={handleSearch}
        classLangUA={"buttonLanguages active"}
        toUA={"/dom/ua"}
        titleLangUA={"UA"}
        classLangRU={"buttonLanguages "}
        toRU={"/dom/ru"}
        titleLangRU={"RU"}
        toHome={"/"}
        toHtml={"/html/ua"}
        toCss={"/css/ua"}
        toScss={"/scss/ua"}
        toJS={"/js/ua"}
        toDom={"/dom/ua"}
        toBom={"/bom/ua"}
        toHttp={"/http/ua"}
        toReact={"/react/ua"}
        toRedux={"/redux/ua"}
        toTS={"/ts/ua"}
        toNext={"/next/ua"}
        nameHome={"Головна сторінка"}
        nameHtml={"HTML5"}
        nameCss={"CSS"}
        nameScss={"SCSS"}
        nameJS={"JavaScript"}
        nameDom={"DOM"}
        nameBom={"BOM"}
        nameHttp={"HTTP"}
        nameReact={"React"}
        nameRedux={"Redux"}
        nameTS={"TypeScript"}
        nameNext={"NextJS"}
      />
      <Container style={{ width: "100%", maxWidth: "none" }}>
        <Button
          id="menu-btnInfo"
          aria-label="open drawer"
          onClick={handleMenuInfoOpen}
          ref={buttonRef}
        >
          DOM
        </Button>
        {isMenuInfoOpen && (
          <div ref={menuRef}>
            <MenuDom
              sectionFirst={"DOM"}
              sectionSecond={"Пошук елементів"}
              sectionThird={"Зміна властивостей елементів HTML"}
              sectionFourth={"Атрибути"}
              sectionFifth={"Класи"}
              sectionSixth={"Методи створення вузлів"}
              sectionSeventh={"Додавання та видалення елементів"}
              sectionEighth={"Клонування елементів"}
              sectionNinth={"Обробник"}
              sectionTenth={"Делегування подій"}
              sectionEleventh={"Події миші"}
              sectionTwelfth={"Події на елементах керування"}
              sectionThirteenth={"Події фокусу"}
              sectionFourteenth={"Клавіатурні події"}
              sectionFifteenth={"CSS events"}
              sectionSixteenth={"Події журналу сесії"}
              sectionSeventeenth={"Події Text Composition"}
              sectionEighteenth={"Події друку"}
              sectionNineteenth={"Події ресурсу"}
              sectionTwentieth={"Мережні події"}
              sectionTwentyFirst={"Події веб-сокетів"}
              sectionTwentySecond={"Події подання"}
              sectionTwentyThird={"Події буфера обміну"}
              sectionTwentyFourth={"Події Drag & Drop"}
              onClose={handleMenuInfoClose}
            />
          </div>
        )}
        <TableContainer>
          <DomModelUA searchTerm={searchTerm} />
          <DomFindElementsUA searchTerm={searchTerm} />
          <ChangePropertiesUA searchTerm={searchTerm} />
          <AttributesClassUA searchTerm={searchTerm} />
          <CreatingNodesUA searchTerm={searchTerm} />
          <ElementsUA searchTerm={searchTerm} />
          <ListenerUA searchTerm={searchTerm} />
          <EventUA searchTerm={searchTerm} />
        </TableContainer>
        <footer className="footer">
          <a
            target="_blank"
            href="https://developer.mozilla.org/en-US/docs/Web/API/Document_Object_Model"
          >
            Документація DOM
          </a>
        </footer>
      </Container>
      <Arrow />
    </>
  );
}
