import React, { useState } from "react";
import { Box, AppBar, Toolbar, IconButton, Typography } from "@mui/material";
import { Link } from "react-router-dom";
import MenuComponent from "./MenuComponent.tsx";
import Search from "./Search.tsx";
import "./appBar.scss";
import { IMenuAppBarProps } from "../types/interface.ts";

export default function SearchAppBar({
  onSearch,
  ...props
}: IMenuAppBarProps & { onSearch: (searchTerm: string) => void }) {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");

  const handleMenuOpen = () => {
    setIsMenuOpen(!isMenuOpen);
  };

  const handleMenuClose = () => {
    setIsMenuOpen(false);
  };

  const handleSearchChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const value = event.target.value;
    setSearchTerm(value);
    onSearch(value);
  };
  const handleClearSearch = () => {
    setSearchTerm("");
    onSearch("");
  };

  return (
    <Box sx={{ flexGrow: 1 }}>
      <AppBar position="static">
        <Toolbar className="header">
          <div className="menu">
            <IconButton
              className="menu-btn"
              aria-label="open drawer"
              onClick={handleMenuOpen}
            ></IconButton>

            <Box className="menu-logo">
              <Typography
                variant="h6"
                noWrap
                sx={{ flexGrow: 1, display: { xs: "none", sm: "block" } }}
              >
                Front-End
              </Typography>
              <Link className="menu-logo-logoLink" to={props.toHome}></Link>
            </Box>
          </div>

          <Search
            onChange={handleSearchChange}
            onClear={handleClearSearch}
            searchTerm={searchTerm}
          />
        </Toolbar>
      </AppBar>

      {isMenuOpen && <MenuComponent {...props} onClose={handleMenuClose} />}
    </Box>
  );
}
