import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import ButtonExample from "../../core/ButtonExample.tsx";
import ButtonExampleWithBtn from "../../core/ButtonExampleWithBtn.tsx";
import {
  asyncConst,
  AwaitConst,
  errorConst,
  promiseConst,
  asyncTwoConst,
} from "./AwaitConstPre.ts";
import { async, Await, error } from "./await.js";
import { IMethodsProps } from "../../types/interface.ts";

export default function AwaitUA({ searchTerm }: IMethodsProps) {
  const tableData = [
    {
      title: "Async",
      textForSearch:
        "Пишеться перед функцією і означає те, що ця функція поверне проміс.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>Async</h3>}
            text={
              <p>
                Пишеться перед функцією і означає те, що ця функція поверне
                проміс.
              </p>
            }
          />
          <ButtonExampleWithBtn
            titleButtonExample={"Приклад Async"}
            title={
              <p id="formated-text">
                <span id="jsasync"></span>
              </p>
            }
            text={
              <pre>
                <code>{asyncConst}</code>
              </pre>
            }
            onClick={async}
          />
        </>
      ),
    },
    {
      title: "Await",
      textForSearch:
        "Виконується всередині async функції. Await чекає поки виконається проміс і потім повертає його результат.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>Await</h3>}
            text={
              <p>
                Виконується всередині async функції. Await чекає поки
                виконається проміс і потім повертає його результат.
              </p>
            }
          />
          <ButtonExampleWithBtn
            titleButtonExample={"Приклад Await"}
            title={
              <p id="formated-text">
                <span id="jsawait"></span>
              </p>
            }
            text={
              <pre>
                <code>{AwaitConst}</code>
              </pre>
            }
            onClick={Await}
          />
        </>
      ),
    },
    {
      title: "Error",
      textForSearch:
        "Для того щоб відловити помилку в async/await використовується try...catch.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>Error</h3>}
            text={
              <p>
                Для того щоб відловити помилку в async/await використовується
                try...catch.
              </p>
            }
          />
          <ButtonExampleWithBtn
            titleButtonExample={"Приклад Error"}
            title={
              <p id="formated-text">
                <span id="jserror"></span>
              </p>
            }
            text={
              <pre>
                <code>{errorConst}</code>
              </pre>
            }
            onClick={error}
          />
        </>
      ),
    },
    {
      title: "Порівняння",
      textForSearch: "Порівняння Async/await з Promise.",
      jsx: (
        <ButtonExample
          titleButtonExample={"Приклад порівняння"}
          title={
            <p id="formated-text">
              Promise
              <pre>
                <code>{promiseConst}</code>
              </pre>
            </p>
          }
          text={
            <p id="formated-text">
              Async/await
              <pre>
                <code>{asyncTwoConst}</code>
              </pre>
            </p>
          }
        />
      ),
    },
  ];

  const filteredData = tableData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredData.length > 0 && (
        <Table id="js_await">
          <TableBody>
            <TableOneCol text={<h3>Async/await.</h3>} />
            {filteredData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
