import React, { useState, useEffect, useRef } from "react";
import Container from "@mui/material/Container";
import TableContainer from "@mui/material/TableContainer";
import TableOneCol from "../../core/TableOneCol.tsx";
import Table from "@mui/material/Table";
import Button from "@mui/material/IconButton";
import Arrow from "../../core/Arrow";
import MenuCss from "./MenuCss.tsx";
import "./css.scss";
import BackgroundUA from "./BackgroundUA.tsx";
import FontUA from "./FontUA.tsx";
import ListUA from "./ListUA.tsx";
import SizeUA from "./SizeUA.tsx";
import PositionUA from "./PositionUA.tsx";
import DisplayUA from "./DisplayUA.tsx";
import BoxModelUA from "./BoxModelUA.tsx";
import AnimationUA from "./AnimationUA.tsx";
import ImageUA from "./ImageUA.tsx";
import TableUA from "./TableUA.tsx";
import PseudoElementsUA from "./PseudoElementsUA.tsx";
import AppBar from "../AppBar.tsx";

export default function CssUA() {
  const [isMenuInfoOpen, setIsMenuInfoOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const menuRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  const handleMenuInfoOpen = () => {
    setIsMenuInfoOpen(!isMenuInfoOpen);
  };

  const handleMenuInfoClose = () => {
    setIsMenuInfoOpen(false);
  };

  useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      if (
        isMenuInfoOpen &&
        menuRef.current &&
        !menuRef.current.contains(event.target as Node) &&
        buttonRef.current &&
        !buttonRef.current.contains(event.target as Node)
      ) {
        setIsMenuInfoOpen(false);
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);

    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
    };
  }, [isMenuInfoOpen]);

  const handleSearch = (term) => {
    setSearchTerm(term);
  };

  return (
    <>
      <AppBar
        onSearch={handleSearch}
        classLangUA={"buttonLanguages active"}
        toUA={"/css/ua"}
        titleLangUA={"UA"}
        classLangRU={"buttonLanguages "}
        toRU={"/css/ru"}
        titleLangRU={"RU"}
        toHome={"/"}
        toHtml={"/html/ua"}
        toCss={"/css/ua"}
        toScss={"/scss/ua"}
        toJS={"/js/ua"}
        toDom={"/dom/ua"}
        toBom={"/bom/ua"}
        toHttp={"/http/ua"}
        toReact={"/react/ua"}
        toRedux={"/redux/ua"}
        toTS={"/ts/ua"}
        toNext={"/next/ua"}
        nameHome={"Головна сторінка"}
        nameHtml={"HTML5"}
        nameCss={"CSS"}
        nameScss={"SCSS"}
        nameJS={"JavaScript"}
        nameDom={"DOM"}
        nameBom={"BOM"}
        nameHttp={"HTTP"}
        nameReact={"React"}
        nameRedux={"Redux"}
        nameTS={"TypeScript"}
        nameNext={"NextJS"}
      />
      <Container style={{ width: "100%", maxWidth: "none" }}>
        <Button
          id="menu-btnInfo"
          aria-label="open drawer"
          onClick={handleMenuInfoOpen}
          ref={buttonRef}
        >
          CSS
        </Button>
        {isMenuInfoOpen && (
          <div ref={menuRef}>
            <MenuCss
              sectionFirst={"Робота з фоном"}
              sectionSecond={"Робота зі шрифтами"}
              sectionThird={"Робота з текстом"}
              sectionFourth={"Додаткові властивості для тексту"}
              sectionFifth={"Робота з макросом"}
              sectionSixth={"Розміри елемента"}
              sectionSeventh={"Позиціонування"}
              sectionEighth={"Відображення елементів"}
              sectionNinth={"Flex"}
              sectionTenth={"Grid"}
              sectionEleventh={"Розміщення елементів"}
              sectionTwelfth={"Блочна модель. Margin"}
              sectionThirteenth={"Padding"}
              sectionFourteenth={"Border"}
              sectionFifteenth={"Анімація"}
              sectionSixteenth={"Трансформація"}
              sectionSeventeenth={"Переходи"}
              sectionEighteenth={"Зображення"}
              sectionNineteenth={"Таблиці"}
              sectionTwentieth={"Псевдоелементи"}
              sectionTwentyFirst={"Псевдокласи"}
              onClose={handleMenuInfoClose}
            />
          </div>
        )}
        <TableContainer>
          <Table id="ts_title">
            <TableOneCol text={<h1>Вивчення CSS.</h1>} />
          </Table>
          <BackgroundUA searchTerm={searchTerm} />
          <FontUA searchTerm={searchTerm} />
          <ListUA searchTerm={searchTerm} />
          <SizeUA searchTerm={searchTerm} />
          <PositionUA searchTerm={searchTerm} />
          <DisplayUA searchTerm={searchTerm} />
          <BoxModelUA searchTerm={searchTerm} />
          <AnimationUA searchTerm={searchTerm} />
          <ImageUA searchTerm={searchTerm} />
          <TableUA searchTerm={searchTerm} />
          <PseudoElementsUA searchTerm={searchTerm} />
        </TableContainer>
        <footer className="footer">
          <a
            target="_blank"
            href="https://developer.mozilla.org/en-US/docs/Web/CSS"
          >
            Документація CSS
          </a>
        </footer>
      </Container>
      <Arrow />
    </>
  );
}
