import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function CreatingNodesUA({ searchTerm }: IMethodsProps) {
  const tableData = [
    {
      title: "document.write(html)",
      category: "DOM",
      textForSearch: "Запис HTML на сторінку, динамічна генерація.",
      jsx: (
        <TableTwoCol
          title={<h3>document.write(html)</h3>}
          text={
            <p>
              Записує html на сторінку «прямо тут і зараз». Рядок html може бути
              динамічно згенерована, тому метод достатньо гнучкий. Ми можемо
              використовувати JavaScript, щоб створити повноцінну веб-сторінку
              та записати її в документ.
            </p>
          }
        />
      ),
    },
    {
      title: "document.createElement(tag)",
      category: "DOM",
      textForSearch: "Створення нового елемента.",
      jsx: (
        <TableTwoCol
          title={<h3>document.createElement(tag)</h3>}
          text={<p>Створює елемент із заданим тегом.</p>}
        />
      ),
    },
    {
      title: "document.createTextNode(value)",
      category: "DOM",
      textForSearch: "Створення текстового вузла.",
      jsx: (
        <TableTwoCol
          title={<h3>document.createTextNode(value)</h3>}
          text={<p>Створює текстовий вузол (рідко використовується).</p>}
        />
      ),
    },
  ];

  const filteredData = tableData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredData.length > 0 && (
        <Table id="dom_createNodes">
          <TableBody>
            <TableOneCol text={<h3>Методи для створення вузлів.</h3>} />
            {filteredData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
