import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import ButtonExample from "../../core/ButtonExample.tsx";
import {
  getRequest,
  getResponse,
  headRequest,
  headResponse,
  postRequest,
  postResponse,
  putRequest,
  putResponse,
  deleteRequest,
  deleteResponse,
} from "./HttpConstPre.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function MethodsUA({ searchTerm }: IMethodsProps) {
  const tableData = [
    {
      title: "GET",
      textForSearch:
        "Запитує представлення ресурсу. Такі запити можуть лише витягувати дані.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>GET</h3>}
            text={
              <p>
                Запитує представлення ресурсу. Такі запити можуть лише
                витягувати дані.
              </p>
            }
          />
          <ButtonExample
            titleButtonExample={"Приклад GET"}
            title={
              <pre>
                <code>{getRequest}</code>
              </pre>
            }
            text={
              <pre>
                <code>{getResponse}</code>
              </pre>
            }
          />
        </>
      ),
    },
    {
      title: "HEAD",
      textForSearch:
        "Запитує ресурс, як і GET, але відповідь приходить без тіла.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>HEAD</h3>}
            text={
              <p>Запитує ресурс, як і GET, але відповідь приходить без тіла.</p>
            }
          />
          <ButtonExample
            titleButtonExample={"Приклад HEAD"}
            title={
              <pre>
                <code>{headRequest}</code>
              </pre>
            }
            text={
              <pre>
                <code>{headResponse}</code>
              </pre>
            }
          />
        </>
      ),
    },
    {
      title: "POST",
      textForSearch:
        "Відправляє сутності до вказаного ресурсу. Може викликати побічні ефекти на сервері та зміну стану.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>POST</h3>}
            text={
              <p>
                Відправляє сутності до вказаного ресурсу. Може викликати побічні
                ефекти на сервері та зміну стану.
              </p>
            }
          />
          <ButtonExample
            titleButtonExample={"Приклад POST"}
            title={
              <pre>
                <code>{postRequest}</code>
              </pre>
            }
            text={
              <pre>
                <code>{postResponse}</code>
              </pre>
            }
          />
        </>
      ),
    },
    {
      title: "PUT",
      textForSearch: "Замінює поточні представлення ресурсу даними запиту.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>PUT</h3>}
            text={<p>Замінює поточні представлення ресурсу даними запиту.</p>}
          />
          <ButtonExample
            titleButtonExample={"Приклад PUT"}
            title={
              <pre>
                <code>{putRequest}</code>
              </pre>
            }
            text={
              <pre>
                <code>{putResponse}</code>
              </pre>
            }
          />
        </>
      ),
    },
    {
      title: "DELETE",
      textForSearch: "Видаляє вказаний ресурс.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>DELETE</h3>}
            text={<p>Видаляє вказаний ресурс.</p>}
          />
          <ButtonExample
            titleButtonExample={"Приклад DELETE"}
            title={
              <pre>
                <code>{deleteRequest}</code>
              </pre>
            }
            text={
              <pre>
                <code>{deleteResponse}</code>
              </pre>
            }
          />
        </>
      ),
    },
    {
      title: "CONNECT",
      textForSearch: "Налаштовує тунель із сервером, визначеним за ресурсом.",
      jsx: (
        <TableTwoCol
          title={<h3>CONNECT</h3>}
          text={<p>Налаштовує тунель із сервером, визначеним за ресурсом.</p>}
        />
      ),
    },
    {
      title: "OPTIONS",
      textForSearch: "Описує параметри з'єднання з ресурсом.",
      jsx: (
        <TableTwoCol
          title={<h3>OPTIONS</h3>}
          text={<p>Описує параметри з'єднання з ресурсом.</p>}
        />
      ),
    },
    {
      title: "TRACE",
      textForSearch:
        "Викликає текстове повідомлення, що повертається, з ресурсу.",
      jsx: (
        <TableTwoCol
          title={<h3>TRACE</h3>}
          text={
            <p>Викликає текстове повідомлення, що повертається, з ресурсу.</p>
          }
        />
      ),
    },
    {
      title: "PATCH",
      textForSearch: "Частково змінює ресурс.",
      jsx: (
        <TableTwoCol
          title={<h3>PATCH</h3>}
          text={<p>Частково змінює ресурс.</p>}
        />
      ),
    },
  ];

  const filteredData = tableData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredData.length > 0 && (
        <Table id="http_method">
          <TableBody>
            <TableOneCol text={<h2>Методи HTTP запиту.</h2>} />
            {filteredData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
