import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function SizeUA({ searchTerm }: IMethodsProps) {
  const tableSize = [
    {
      title: "height",
      category: "Розміри",
      textForSearch: "Дозволяє задавати висоту елемента.",
      jsx: (
        <TableTwoCol
          title={<h3>height:</h3>}
          text={<p>Дозволяє позначати висоту елемента.</p>}
        />
      ),
    },
    {
      title: "max-height",
      category: "Розміри",
      textForSearch: "Встановлює максимальну висоту елемента.",
      jsx: (
        <TableTwoCol
          title={<h3>max-height:</h3>}
          text={<p>Встановлює максимальну висоту елемента.</p>}
        />
      ),
    },
    {
      title: "min-height",
      category: "Розміри",
      textForSearch: "Встановлює мінімальну висоту елемента.",
      jsx: (
        <TableTwoCol
          title={<h3>min-height:</h3>}
          text={<p>Встановлює мінімальну висоту елемента.</p>}
        />
      ),
    },
    {
      title: "width",
      category: "Розміри",
      textForSearch: "Дозволяє задавати ширину елемента.",
      jsx: (
        <TableTwoCol
          title={<h3>width:</h3>}
          text={<p>Дозволяє позначати ширину елемента.</p>}
        />
      ),
    },
    {
      title: "max-width",
      category: "Розміри",
      textForSearch: "Встановлює максимальну ширину елемента.",
      jsx: (
        <TableTwoCol
          title={<h3>max-width:</h3>}
          text={<p>Встановлює максимальну ширину елемента.</p>}
        />
      ),
    },
    {
      title: "min-width",
      category: "Розміри",
      textForSearch: "Встановлює мінімальну ширину елемента.",
      jsx: (
        <TableTwoCol
          title={<h3>min-width:</h3>}
          text={<p>Встановлює мінімальну ширину елемента.</p>}
        />
      ),
    },
    {
      title: "max-block-size",
      category: "Розміри",
      textForSearch:
        "Визначає максимальний горизонтальний або вертикальний розмір блоку елемента.",
      jsx: (
        <TableTwoCol
          title={<h3>max-block-size:</h3>}
          text={
            <p>
              Визначає максимальний горизонтальний або вертикальний розмір блоку
              елемента.
            </p>
          }
        />
      ),
    },
    {
      title: "min-block-size",
      category: "Розміри",
      textForSearch:
        "Визначає мінімальний горизонтальний або вертикальний розмір блоку елемента.",
      jsx: (
        <TableTwoCol
          title={<h3>min-block-size:</h3>}
          text={
            <p>
              Визначає мінімальний горизонтальний або вертикальний розмір блоку
              елемента.
            </p>
          }
        />
      ),
    },
    {
      title: "max-inline-size",
      category: "Розміри",
      textForSearch:
        "Визначає максимальний розмір блоку елемента по горизонталі або вертикалі в залежності від режиму запису.",
      jsx: (
        <TableTwoCol
          title={<h3>max-inline-size:</h3>}
          text={
            <p>
              Визначає максимальний розмір блоку елемента по горизонталі або
              вертикалі залежно від режиму запису.
            </p>
          }
        />
      ),
    },
    {
      title: "min-inline-size",
      category: "Розміри",
      textForSearch:
        "Визначає мінімальний розмір блоку елемента по горизонталі або вертикалі в залежності від режиму запису.",
      jsx: (
        <TableTwoCol
          title={<h3>min-inline-size:</h3>}
          text={
            <p>
              Визначає мінімальний розмір блоку елемента по горизонталі або
              вертикалі залежно від режиму запису.
            </p>
          }
        />
      ),
    },
  ];

  const filteredSize = tableSize.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredSize.length > 0 && (
        <Table id="css_size">
          <TableBody>
            <TableOneCol text={<h2>Розміри елемента.</h2>} />
            {filteredSize.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
