import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function CreatingNodesRU({ searchTerm }: IMethodsProps) {
  const tableData = [
    {
      title: "document.write(html)",
      category: "DOM",
      textForSearch: "Запись HTML на страницу, динамическая генерация.",
      jsx: (
        <TableTwoCol
          title={<h3>document.write(html)</h3>}
          text={
            <p>
              Записывает html на страницу «прямо здесь и сейчас». Строка html
              может быть динамически сгенерирована, поэтому метод достаточно
              гибкий. Мы можем использовать JavaScript, чтобы создать
              полноценную веб-страницу и записать её в документ.
            </p>
          }
        />
      ),
    },
    {
      title: "document.createElement(tag)",
      category: "DOM",
      textForSearch: "Создание нового элемента.",
      jsx: (
        <TableTwoCol
          title={<h3>document.createElement(tag)</h3>}
          text={<p>Создаёт элемент с заданным тегом.</p>}
        />
      ),
    },
    {
      title: "document.createTextNode(value)",
      category: "DOM",
      textForSearch: "Создание текстового узла.",
      jsx: (
        <TableTwoCol
          title={<h3>document.createTextNode(value)</h3>}
          text={<p>Создаёт текстовый узел (редко используется).</p>}
        />
      ),
    },
  ];

  const filteredData = tableData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredData.length > 0 && (
        <Table id="dom_createNodes">
          <TableBody>
            <TableOneCol text={<h3>Методы для создания узлов.</h3>} />
            {filteredData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
