import React from "react";
import AppBar from "../components/AppBar.tsx";
import { Helmet } from "react-helmet";

export default function ReactPageRU() {
  return (
    <>
      <Helmet>
        <title>Next документация</title>
      </Helmet>
      <AppBar
        classLangUA={"buttonLanguages"}
        toUA={"/next/ua"}
        titleLangUA={"UA"}
        classLangRU={"buttonLanguages active"}
        toRU={"/next/ru"}
        titleLangRU={"RU"}
        home={"/home/ru"}
        toHome={"/home/ru"}
        toHtml={"/html/ru"}
        toCss={"/css/ru"}
        toScss={"/scss/ru"}
        toJS={"/js/ru"}
        toDom={"/dom/ru"}
        toBom={"/bom/ru"}
        toHttp={"/http/ru"}
        toReact={"/react/ru"}
        toRedux={"/redux/ru"}
        toTS={"/ts/ru"}
        toNext={"/next/ru"}
        nameHome={"Главная страница"}
        nameHtml={"HTML5"}
        nameCss={"CSS"}
        nameScss={"SCSS"}
        nameJS={"JavaScript"}
        nameDom={"DOM"}
        nameBom={"BOM"}
        nameHttp={"HTTP"}
        nameReact={"React"}
        nameRedux={"Redux"}
        nameTS={"TypeScript"}
        nameNext={"NextJS"}
      />
      <h1>next ru</h1>
    </>
  );
}
