  const filteredProperties = tableData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredConsoleMethods = consoleMethods.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      <Table id="bom_title">
        <TableBody>
          <TableOneCol text={<h1>Робота з BOM.</h1>} />
          {filteredProperties.length > 0 &&
            filteredConsoleMethods.length > 0 && (
              <>
                <TableOneCol text={<h2>Window</h2>} />
                <TableOneCol
                  text={
                    <p>
                      Глобальний об'єкт надає змінні та функції, доступні у
                      будь-якому місці програми. За замовчуванням це ті, що
                      вбудовані в мову чи середовище виконання.
                    </p>
                  }
                />
              </>
            )}
        </TableBody>
      </Table>

      {filteredProperties.length > 0 && (
        <Table id="bom_properties">
          <TableBody>
            <TableOneCol text={<h2>Властивості.</h2>} />
            {filteredProperties.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}

      {filteredConsoleMethods.length > 0 && (
        <Table id="bom_console">
          <TableBody>
            <TableOneCol text={<h3>Методи console.</h3>} />
            {filteredConsoleMethods.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
