import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import { IMethodsProps } from "../../types/interface.ts";

const dom = require("../../images/dom.png");
const domLinks = require("../../images/dom-links.png");
const domLinksElements = require("../../images/dom-links-elements.png");

export default function DomModelUA({ searchTerm }: IMethodsProps) {
  const tableData = [
    {
      title: "Document Object Model",
      category: "DOM",
      textForSearch: "Document Object Model, DOM, об'єктна модель документа.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                DOM – це об'єктна модель документа, яку браузер створює в
                пам'яті комп'ютера на основі HTML-коду, отриманого ним від
                сервера. Якщо сказати по-простому, HTML-код – це текст сторінки,
                а DOM – це набір пов'язаних об'єктів, створених браузером при
                парсингу її тексту.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "Структура DOM-дерева",
      category: "DOM",
      textForSearch: "Структура DOM, вузли DOM-дерева.",
      jsx: (
        <TableTwoCol
          title={
            <p>
              <img className="dom_images" src={dom} alt="dom" />
            </p>
          }
          text={
            <p>
              Вузол html утворений елементом <b>&lt;html&gt;</b>. Вузли{" "}
              <b>&lt;head&gt;</b> та <b>&lt;body&gt;</b> мають батьківський
              зв'язок з <b>&lt;html&gt;</b>. Вузол <b>&lt;head&gt;</b>{" "}
              пов'язаний з<b>&lt;link&gt;</b>, <b>&lt;meta&gt;</b> та{" "}
              <b>&lt;title&gt;</b> та є для них батьком. В свою чергу
              <b>&lt;body&gt;</b> пов'язаний з <b>&lt;header&gt;</b>,{" "}
              <b>&lt;section&gt;</b> та <b>&lt;footer&gt;</b> і є для них
              батьком. Елемент <b>&lt;section&gt;</b> має трьох дітей
              <b>&lt;div&gt;</b>, <b>&lt;p&gt;</b> та <b>&lt;a&gt;</b>. <br />
              Не знаючи як влаштовано DOM-дерево та зв'язки між вузлами, знайти
              якийсь певний елемент у ньому буде досить важко.
            </p>
          }
        />
      ),
    },
    {
      title: "Навігація по DOM",
      category: "DOM",
      textForSearch: "Навігація DOM, document, childNodes, parentNode.",
      jsx: (
        <TableTwoCol
          title={
            <p>
              <img className="dom_images" src={domLinks} alt="dom-links" />
            </p>
          }
          text={
            <p>
              DOM дозволяє нам робити будь-що з елементами та їх вмістом, але
              спочатку потрібно отримати відповідний DOM-об'єкт.
              <br />
              Усі операції з DOM починаються з об'єкта <b>document</b>. Це
              головна "точка входу" в DOM. З нього ми можемо отримати доступ до
              будь-якого вузлу. <br />
              Так виглядають основні посилання, за якими можна переходити між
              вузлами DOM.
            </p>
          }
        />
      ),
    },
    {
      title: "document.documentElement",
      category: "DOM",
      textForSearch: "document.documentElement, кореневий вузол.",
      jsx: (
        <TableTwoCol
          title={<h3>document.documentElement</h3>}
          text={
            <p>
              Найвищий вузол документа відповідає тегу <b>&lt;html&gt;</b>.
            </p>
          }
        />
      ),
    },
    {
      title: "document.head",
      category: "DOM",
      textForSearch: "document.head, вузол head.",
      jsx: (
        <TableTwoCol
          title={<h3>document.head</h3>}
          text={
            <p>
              Застосовується до тега <b>&lt;head&gt;</b>.
            </p>
          }
        />
      ),
    },
    {
      title: "document.body",
      category: "DOM",
      textForSearch: "document.body, вузол body.",
      jsx: (
        <TableTwoCol
          title={<h3>document.body</h3>}
          text={
            <p>
              Інший часто використовуваний DOM-вузол – вузол тега{" "}
              <b>&lt;body&gt;</b>. Для скорочення коду надалі використовуємо
              змінну. <br />
              <code>const bodyElement = document.body;</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".childNodes",
      category: "DOM",
      textForSearch: "childNodes, список дочірніх вузлів.",
      jsx: (
        <TableTwoCol
          title={<h3>.childNodes</h3>}
          text={
            <p>
              Має список усіх дітей, включаючи текстові вузли.
              <br />
              <code>bodyElement.childNodes</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".hasChildNodes",
      category: "DOM",
      textForSearch: "hasChildNodes, перевірка наявності дочірніх вузлів.",
      jsx: (
        <TableTwoCol
          title={<h3>.hasChildNodes</h3>}
          text={
            <p>
              Для перевірки чи є у елемента дочірні вузли.
              <br />
              <code>bodyElement.hasChildNodes()</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".firstChild",
      category: "DOM",
      textForSearch: "firstChild, перший дочірній вузол.",
      jsx: (
        <TableTwoCol
          title={<h3>.firstChild</h3>}
          text={
            <p>
              Забезпечує швидкий доступ до першого дочірнього вузла.
              <br />
              <code>bodyElement.firstChild</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".lastChild",
      category: "DOM",
      textForSearch: "lastChild, останній дочірній вузол.",
      jsx: (
        <TableTwoCol
          title={<h3>.lastChild</h3>}
          text={
            <p>
              Забезпечує швидкий доступ до останнього дочірнього вузла.
              <br />
              <code>bodyElement.lastChild</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".previousSibling",
      category: "DOM",
      textForSearch: "previousSibling, попередній сусідній вузол.",
      jsx: (
        <TableTwoCol
          title={<h3>.previousSibling</h3>}
          text={
            <p>
              Попередній вузол того ж батька.{" "}
              <code>bodyElement.previousSibling</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".nextSibling",
      category: "DOM",
      textForSearch: "nextSibling, наступний сусідній вузол.",
      jsx: (
        <TableTwoCol
          title={<h3>.nextSibling</h3>}
          text={
            <p>
              Наступний вузол того ж батька.{" "}
              <code>bodyElement.nextSibling</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".parentNode",
      category: "DOM",
      textForSearch: "parentNode, батьківський вузол.",
      jsx: (
        <TableTwoCol
          title={<h3>.parentNode</h3>}
          text={
            <p>
              Батько. <code>bodyElement.parentNode</code>
            </p>
          }
        />
      ),
    },
    {
      title: "Навігація лише елементами",
      category: "DOM",
      textForSearch:
        "Навігація по елементах, children, firstElementChild, lastElementChild.",
      jsx: (
        <TableTwoCol
          title={
            <p>
              <img
                className="dom_images"
                src={domLinksElements}
                alt="dom-links"
              />
            </p>
          }
          text={
            <p>
              Навігаційні властивості, описані вище, відносяться до всіх вузлів
              у документі. Зокрема, в <b>childNodes</b> знаходяться і текстові
              вузли, вузли-елементи та вузли-коментарі, якщо вони є.
              <br />
              Але для більшості завдань текстові вузли та вузли-коментарі нам не
              потрібні. Ми хочемо маніпулювати вузлами-елементами, які є тегами
              і формують структуру сторінки.
              <br />
              Тому давайте розглянемо додатковий набір посилань, які враховують
              лише вузли-елементи.
            </p>
          }
        />
      ),
    },
    {
      title: ".children",
      category: "DOM",
      textForSearch: "children, колекція дочірніх елементів.",
      jsx: (
        <TableTwoCol
          title={<h3>.children</h3>}
          text={
            <p>
              Колекція дітей, які є елементами.{" "}
              <code>bodyElement.children</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".firstElementChild",
      category: "DOM",
      textForSearch: "firstElementChild, перший дочірній елемент.",
      jsx: (
        <TableTwoCol
          title={<h3>.firstElementChild</h3>}
          text={
            <p>
              Перший дочірній елемент.{" "}
              <code>bodyElement.firstElementChild</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".lastElementChild",
      category: "DOM",
      textForSearch: "lastElementChild, останній дочірній елемент.",
      jsx: (
        <TableTwoCol
          title={<h3>.lastElementChild</h3>}
          text={
            <p>
              Останній дочірній елемент.{" "}
              <code>bodyElement.lastElementChild</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".previousElementSibling",
      category: "DOM",
      textForSearch: "previousElementSibling, попередній сусідній елемент.",
      jsx: (
        <TableTwoCol
          title={<h3>.previousElementSibling</h3>}
          text={
            <p>
              Попередній сусідній елемент.{" "}
              <code>bodyElement.previousElementSibling</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".nextElementSibling",
      category: "DOM",
      textForSearch: "nextElementSibling, наступний сусідній елемент.",
      jsx: (
        <TableTwoCol
          title={<h3>.nextElementSibling</h3>}
          text={
            <p>
              Наступний сусідній елемент.{" "}
              <code>bodyElement.nextElementSibling</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".parentElement",
      category: "DOM",
      textForSearch: "parentElement, батьківський елемент.",
      jsx: (
        <TableTwoCol
          title={<h3>.parentElement</h3>}
          text={
            <p>
              Батьківський елемент. <code>bodyElement.parentElement</code>
            </p>
          }
        />
      ),
    },
  ];

  const filteredData = tableData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredData.length > 0 && (
        <Table id="dom_title">
          <TableBody>
            <TableOneCol text={<h1>Вивчення CSS.</h1>} />
            <TableOneCol text={<h2>Document Object Model.</h2>} />
            {filteredData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
