import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function InteractiveRU({ searchTerm }: IMethodsProps) {
  const interactiveData = [
    {
      title: "Интерактивные элементы",
      category: "HTML",
      textForSearch: "Интерактивные элементы, <details>, <dialog>, <summary>.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                HTML содержит в себе элементы, которые помогают создавать
                интерактивные объекты пользовательского интерфейса.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "<details>",
      category: "HTML",
      textForSearch: "<details>, скрытая информация, раскрытие информации.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;details&gt; &lt;/details&gt;</h3>}
          text={
            <p>
              Используется для раскрытия скрытой (дополнительной) информации.
            </p>
          }
        />
      ),
    },
    {
      title: "<dialog>",
      category: "HTML",
      textForSearch: "<dialog>, диалоговое окно, интерактивный элемент.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;dialog&gt; &lt;/dialog&gt;</h3>}
          text={
            <p>
              Определяет диалоговое окно или другой интерактивный элемент, такой
              как инспектор или окно. Элементы &lt;form&gt; могут
              интегрироваться с диалогом с помощью указания атрибута{" "}
              <b>method="dialog"</b>. Когда отправляется такая форма, диалог
              закрывается с returnValue равным value нажатой кнопки submit.
            </p>
          }
        />
      ),
    },
    {
      title: "<summary>",
      category: "HTML",
      textForSearch: "<summary>, сводка, заголовок, легенда, details.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;summary&gt; &lt;/summary&gt;</h3>}
          text={
            <p>
              Определяет сводку, заголовок или легенду для &lt;details&gt; поля
              раскрытия элемента. Щелчок по &lt;summary&gt; элементу переключает
              состояние родительского &lt;details&gt; элемента открытым и
              закрытым.
            </p>
          }
        />
      ),
    },
  ];

  const filteredInteractiveData = interactiveData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredInteractiveData.length > 0 && (
        <Table id="html_interactive">
          <TableBody>
            <TableOneCol text={<h2>Интерактивные элементы.</h2>} />
            {filteredInteractiveData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
