import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function ListUA({ searchTerm }: IMethodsProps) {
  const tableList = [
    {
      title: "list-style",
      category: "Списки",
      textForSearch:
        "Універсальна властивість, що дозволяє одночасно встановити стиль маркера, його положення, а також зображення.",
      jsx: (
        <TableTwoCol
          title={<h3>list-style:</h3>}
          text={
            <p>
              Універсальна властивість, що дозволяє одночасно встановити стиль
              маркера, його положення, а також зображення, яке буде
              використовуватися як маркер.
            </p>
          }
        />
      ),
    },
    {
      title: "list-style-image",
      category: "Списки",
      textForSearch:
        "Дозволяє вставити картинку замість макросу. Значення: none, url, inherit.",
      jsx: (
        <TableTwoCol
          title={<h3>list-style-image:</h3>}
          text={
            <p>
              Дозволяє вставити картинку замість макросу. <br />
              none - Скасує зображення як маркер для батьківського елемента.
              <br />
              url - Відносний чи абсолютний шлях до графічного файлу.
            </p>
          }
        />
      ),
    },
    {
      title: "list-style-position",
      category: "Списки",
      textForSearch: "Обтічність макросу. Значення: inside, outside.",
      jsx: (
        <TableTwoCol
          title={<h3>list-style-position:</h3>}
          text={
            <p>
              Обтічність макросу. <br />
              inside - Маркер є частиною текстового блоку та відображається в
              елементі списку. <br />
              outside - Текст вирівнюється по лівому краю, а маркери
              розміщуються за межами текстового блоку.
            </p>
          }
        />
      ),
    },
    {
      title: "list-style-type",
      category: "Списки",
      textForSearch:
        "Змінює вигляд макросу (маркера). Значення: circle, disc, square, decimal, lower-roman, upper-alpha, none тощо.",
      jsx: (
        <TableTwoCol
          title={<h3>list-style-type:</h3>}
          text={
            <p>
              Змінює вигляд макросу. <br />
              circle - Маркер у вигляді гуртка. <br />
              disc - Маркер у вигляді крапки. <br />
              square - Маркер у вигляді квадрата.
              <br />
              decimal - Арабські числа (1, 2, 3, 4, ...). <br />
              lower-alpha - Рядкові латинські літери (a, b, c, d,...).
              <br />
              lower-roman - Римські числа в нижньому регістрі (i, ii, iii,...).{" "}
              <br />
              upper-alpha - Великі латинські літери (A, B, C, D,...). <br />
              upper-roman - Римські числа у верхньому регістрі (I, II, III,...).
            </p>
          }
        />
      ),
    },
  ];

  const filteredList = tableList.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredList.length > 0 && (
        <Table id="css_list">
          <TableBody>
            <TableOneCol text={<h3>Робота з макросом.</h3>} />
            {filteredList.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
