import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function ListRU({ searchTerm }: IMethodsProps) {
  const tableList = [
    {
      title: "list-style",
      category: "Списки",
      textForSearch:
        "Универсальное свойство, позволяющее одновременно задать стиль маркера, его положение, а также изображение.",
      jsx: (
        <TableTwoCol
          title={<h3>list-style:</h3>}
          text={
            <p>
              Универсальное свойство, позволяющее одновременно задать стиль
              маркера, его положение, а также изображение, которое будет
              использоваться в качестве маркера.
            </p>
          }
        />
      ),
    },
    {
      title: "list-style-image",
      category: "Списки",
      textForSearch:
        "Позволяет вставить картинку вместо маркера. Значения: none, url, inherit.",
      jsx: (
        <TableTwoCol
          title={<h3>list-style-image:</h3>}
          text={
            <p>
              Позволяет вставить картинку вместо маркера. <br />
              none - Отменяет изображение в качестве маркера для родительского
              элемента. <br />
              url - Относительный или абсолютный путь к графическому файлу.
            </p>
          }
        />
      ),
    },
    {
      title: "list-style-position",
      category: "Списки",
      textForSearch: "Обтекаемость маркера. Значения: inside, outside.",
      jsx: (
        <TableTwoCol
          title={<h3>list-style-position:</h3>}
          text={
            <p>
              Обтекаемость маркера. <br />
              inside - Маркер является частью текстового блока и отображается в
              элементе списка. <br />
              outside - Текст выравнивается по левому краю, а маркеры
              размещаются за пределами текстового блока.
            </p>
          }
        />
      ),
    },
    {
      title: "list-style-type",
      category: "Списки",
      textForSearch:
        "Меняет вид маркера. Значения: circle, disc, square, decimal, lower-roman, upper-alpha, none и т.д.",
      jsx: (
        <TableTwoCol
          title={<h3>list-style-type:</h3>}
          text={
            <p>
              Меняет вид маркера. <br />
              circle - Маркер в виде кружка. <br />
              disc - Маркер в виде точки. <br />
              square - Маркер в виде квадрата.
              <br />
              decimal - Арабские числа (1, 2, 3, 4, ...). <br />
              lower-alpha - Строчные латинские буквы (a, b, c, d,...).
              <br />
              lower-roman - Римские числа в нижнем регистре (i, ii, iii,...).{" "}
              <br />
              upper-alpha - Заглавные латинские буквы (A, B, C, D,...). <br />
              upper-roman - Римские числа в верхнем регистре (I, II, III,...).
            </p>
          }
        />
      ),
    },
  ];

  const filteredList = tableList.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredList.length > 0 && (
        <Table id="css_list">
          <TableBody>
            <TableOneCol text={<h3>Работа с маркером.</h3>} />
            {filteredList.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
