import React, { useState, useEffect, useRef } from "react";
import Container from "@mui/material/Container";
import TableContainer from "@mui/material/TableContainer";
import TableOneCol from "../../core/TableOneCol.tsx";
import Table from "@mui/material/Table";
import Button from "@mui/material/IconButton";
import Arrow from "../../core/Arrow";
import MenuCss from "./MenuCss.tsx";
import "./css.scss";
import BackgroundRU from "./BackgroundRU.tsx";
import FontRU from "./FontRU.tsx";
import ListRU from "./ListRU.tsx";
import SizeRU from "./SizeRU.tsx";
import PositionRU from "./PositionRU.tsx";
import DisplayRU from "./DisplayRU.tsx";
import BoxModelRU from "./BoxModelRU.tsx";
import AnimationRU from "./AnimationRU.tsx";
import ImageRU from "./ImageRU.tsx";
import TableRU from "./TableRU.tsx";
import PseudoElementsRU from "./PseudoElementsRU.tsx";
import AppBar from "../AppBar.tsx";

export default function CssRU() {
  const [isMenuInfoOpen, setIsMenuInfoOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const menuRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  const handleMenuInfoOpen = () => {
    setIsMenuInfoOpen(!isMenuInfoOpen);
  };

  const handleMenuInfoClose = () => {
    setIsMenuInfoOpen(false);
  };

  useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      if (
        isMenuInfoOpen &&
        menuRef.current &&
        !menuRef.current.contains(event.target as Node) &&
        buttonRef.current &&
        !buttonRef.current.contains(event.target as Node)
      ) {
        setIsMenuInfoOpen(false);
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);

    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
    };
  }, [isMenuInfoOpen]);

  const handleSearch = (term) => {
    setSearchTerm(term);
  };

  return (
    <>
      <AppBar
        onSearch={handleSearch}
        classLangUA={"buttonLanguages"}
        toUA={"/css/ua"}
        titleLangUA={"UA"}
        classLangRU={"buttonLanguages active"}
        toRU={"/css/ru"}
        titleLangRU={"RU"}
        toHome={"/home/ru"}
        toHtml={"/html/ru"}
        toCss={"/css/ru"}
        toScss={"/scss/ru"}
        toJS={"/js/ru"}
        toDom={"/dom/ru"}
        toBom={"/bom/ru"}
        toHttp={"/http/ru"}
        toReact={"/react/ru"}
        toRedux={"/redux/ru"}
        toTS={"/ts/ru"}
        toNext={"/next/ru"}
        nameHome={"Главная страница"}
        nameHtml={"HTML5"}
        nameCss={"CSS"}
        nameScss={"SCSS"}
        nameJS={"JavaScript"}
        nameDom={"DOM"}
        nameBom={"BOM"}
        nameHttp={"HTTP"}
        nameReact={"React"}
        nameRedux={"Redux"}
        nameTS={"TypeScript"}
        nameNext={"NextJS"}
      />
      <Container style={{ width: "100%", maxWidth: "none" }}>
        <Button
          id="menu-btnInfo"
          aria-label="open drawer"
          onClick={handleMenuInfoOpen}
          ref={buttonRef}
        >
          CSS
        </Button>
        {isMenuInfoOpen && (
          <div ref={menuRef}>
            <MenuCss
              sectionFirst={"Работа с фоном"}
              sectionSecond={"Работа с шрифтами"}
              sectionThird={"Работа с текстом"}
              sectionFourth={"Дополнительные свойства для текста"}
              sectionFifth={"Работа с макросом"}
              sectionSixth={"Размеры элемента"}
              sectionSeventh={"Позиционирование"}
              sectionEighth={"Отображение элементов"}
              sectionNinth={"Flex"}
              sectionTenth={"Grid"}
              sectionEleventh={"Размещение элементов"}
              sectionTwelfth={"Блочная модель. Margin"}
              sectionThirteenth={"Padding"}
              sectionFourteenth={"Border"}
              sectionFifteenth={"Анимация"}
              sectionSixteenth={"Трансформация"}
              sectionSeventeenth={"Переходы"}
              sectionEighteenth={"Изображения"}
              sectionNineteenth={"Таблицы"}
              sectionTwentieth={"Псевдоэлементы"}
              sectionTwentyFirst={"Псевдоклассы"}
              onClose={handleMenuInfoClose}
            />
          </div>
        )}
        <TableContainer>
          <Table id="ts_title">
            <TableOneCol text={<h1>Изучение CSS.</h1>} />
          </Table>
          <BackgroundRU searchTerm={searchTerm} />
          <FontRU searchTerm={searchTerm} />
          <ListRU searchTerm={searchTerm} />
          <SizeRU searchTerm={searchTerm} />
          <PositionRU searchTerm={searchTerm} />
          <DisplayRU searchTerm={searchTerm} />
          <BoxModelRU searchTerm={searchTerm} />
          <AnimationRU searchTerm={searchTerm} />
          <ImageRU searchTerm={searchTerm} />
          <TableRU searchTerm={searchTerm} />
          <PseudoElementsRU searchTerm={searchTerm} />
        </TableContainer>
        <footer className="footer">
          <a
            target="_blank"
            href="https://developer.mozilla.org/ru/docs/Web/CSS"
          >
            Документация CSS
          </a>
        </footer>
      </Container>
      <Arrow />
    </>
  );
}
