import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoEqualCol from "../../core/TableTwoEqualCol.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function ImportUA({ searchTerm }: IMethodsProps) {
  const scssImportData = [
    {
      title: "Директива @import",
      category: "SCSS",
      textForSearch: "@import.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Для підключення одного файлу SCSS до іншого використовується
                директива @import. Це дозволяє розділити код на модулі, що
                робить його більш організованим та зручним для підтримки. При
                компіляції SCSS-файлів всі @import директиви будуть замінені
                вмістом відповідних файлів, у результаті буде створено один
                великий CSS-файл.
                <br />
                Компілятор шукає інші файли sass в поточній папці та в каталозі
                файлів sass. Додаткові каталоги пошуку можна задавати за
                допомогою опції `:load_paths` або `--load-path` в командному
                рядку. <br />
                @import шукає Sass-файли, але є кілька правил, за якими @import
                працює як CSS-правило:
                <br />
                Якщо розширення файлу .css <br />
                Якщо ім'я файлу починається з http:// <br />
                Якщо ім'я файлу викликається через url()
                <br />
                Якщо правило @import містить будь-які медіа-запити <br />
                Якщо жодна з перерахованих вище умов не дотримана, а розширення
                файлів .scss або .sass, то ці файли будуть імпортовані. Якщо
                розширення файлів не вказано, то Sass спробує знайти файли за
                іменем з розширенням .scss або .sass та імпортує їх. Наприклад:
              </p>
            }
          />
          <TableTwoEqualCol
            title={
              <p>
                scss <br />
                <br />
                @import "foo.css"; <br />
                @import "foo" screen; <br />
                @import "http://foo.com/bar"; <br />
                @import url(foo);
              </p>
            }
            text={
              <p>
                css <br />
                <br />
                @import "foo.css"; <br />
                @import "foo" screen; <br />
                @import "http://foo.com/bar"; <br />
                @import url(foo);
              </p>
            }
          />
        </>
      ),
    },
  ];

  const filteredScssImportData = scssImportData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredScssImportData.length > 0 && (
        <Table id="scss_import">
          <TableBody>
            <TableOneCol text={<h2>Директиви.</h2>} />
            <TableOneCol text={<h3>@import</h3>} />
            {filteredScssImportData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
