import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import ButtonExampleWithBtn from "../../core/ButtonExampleWithBtn.tsx";
import { changeStyle, getComputedStyle } from "./DomConstPre.tsx";
import { changeStyleFn, getStyle } from "./DomFunc.js";
import { IMethodsProps } from "../../types/interface.ts";

export default function ChangePropertiesUA({ searchTerm }: IMethodsProps) {
  const tableData = [
    {
      title: ".innerHTML",
      category: "DOM",
      textForSearch: "Зміна внутрішнього HTML вмісту.",
      jsx: (
        <TableTwoCol
          title={<h3>.innerHTML</h3>}
          text={
            <p>
              Змінює внутрішній HTML елемент.
              <br />
              <code>element.innerHTML = "новий вміст html"</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".outerHTML",
      category: "DOM",
      textForSearch: "Зміна елемента цілком разом із вмістом.",
      jsx: (
        <TableTwoCol
          title={<h3>.outerHTML</h3>}
          text={
            <p>
              Відмінність від innerHTML полягає в тому, що крім вмісту ми
              отримуємо об'єкт цілком.
              <br />
              <code>element.outerHTML = "новий вміст html"</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".insertAdjacentHTML",
      category: "DOM",
      textForSearch: "Вставка довільного HTML в будь-яке місце.",
      jsx: (
        <TableTwoCol
          title={<h3>.insertAdjacentHTML</h3>}
          text={
            <p>
              Дозволяє вставляти довільний HTML у будь-яке місце документа, в
              тому числі і між вузлами!
              <br />
              <b>html</b> - Рядок HTML, який потрібно вставити. <br />
              <b>where</b> - Куди по відношенню до <b>elem</b> вставляти рядок.
              Усього чотири варіанти: <br />
              <code>beforeBegin</code> - перед <b>elem</b>. <br />
              <code>afterBegin</code> – всередину <b>elem</b>, у саме початок.{" "}
              <br />
              <code>beforeEnd</code> – всередину <b>elem</b>, наприкінці. <br />
              <code>afterEnd</code> – після <b>elem</b>. <br />
              <code>element.insertAdjacentHTML(where, html);</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".insertAdjacentElement",
      category: "DOM",
      textForSearch: "Додавання елемента в DOM-дерево.",
      jsx: (
        <TableTwoCol
          title={<h3>.insertAdjacentElement</h3>}
          text={
            <p>
              Метод додає переданий елемент у DOM-дерево щодо елемента, що
              спричинив метод.
              <br />
              <b>element</b> - Елемент, що додається до DOM-дерева. <br />
              <b>where</b> - Куди до <b>elem</b> вставляти рядок. Усього чотири
              варіанти:
              <br />
              <code>beforeBegin</code> - перед <b>elem</b>. <br />
              <code>afterBegin</code> – всередину <b>elem</b>, у саме початок.{" "}
              <br />
              <code>beforeEnd</code> – всередину <b>elem</b>, наприкінці. <br />
              <code>afterEnd</code> – після <b>elem</b>. <br />
              <code>element.insertAdjacentElement(where, element);</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".insertAdjacentText",
      category: "DOM",
      textForSearch: "Додавання текстового вузла.",
      jsx: (
        <TableTwoCol
          title={<h3>.insertAdjacentText</h3>}
          text={
            <p>
              Метод поміщає заданий текстовий вузол у вказану позицію щодо
              елемента, який переданий у виклик методу.
              <br />
              <b>element</b> - Текст, який буде поміщений у задану позицію.
              <br />
              <b>where</b> - Куди по відношенню до <b>elem</b> вставляти рядок.
              Усього чотири варіанти: <br />
              <code>beforeBegin</code> - перед <b>elem</b>. <br />
              <code>afterBegin</code> – всередину <b>elem</b>, у саме початок.{" "}
              <br />
              <code>beforeEnd</code> – всередину <b>elem</b>, наприкінці. <br />
              <code>afterEnd</code> – після <b>elem</b>. <br />
              <code>element.insertAdjacentText(where, element);</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".textContent",
      category: "DOM",
      textForSearch: "Отримання/зміна текстового вмісту.",
      jsx: (
        <TableTwoCol
          title={<h3>.textContent</h3>}
          text={
            <p>
              Дозволяє отримати безпосередньо вміст. При цьому внесені зміни
              передаються у вигляді рядка повністю. <br />
              <code>element.textContent = "новий вміст html"</code>
            </p>
          }
        />
      ),
    },
    {
      title: "Приклад зміни стилів",
      category: "DOM",
      textForSearch: "Приклад зміни стилів елемента в JavaScript.",
      jsx: (
        <ButtonExampleWithBtn
          titleButtonExample={"Приклад style"}
          title={
            <p id="formated-text">
              <span id="style-text">Початковий текст.</span>
            </p>
          }
          text={
            <pre>
              <code>{changeStyle}</code>
            </pre>
          }
          onClick={changeStyleFn}
        />
      ),
    },
    {
      title: "getComputedStyle",
      category: "DOM",
      textForSearch: "Отримання всіх стилів елемента.",
      jsx: (
        <TableTwoCol
          title={<h3>getComputedStyle</h3>}
          text={
            <p>
              Дозволяє отримати всі стилі елемента. <br />
              <code>getComputedStyle(element)</code>
            </p>
          }
        />
      ),
    },
    {
      title: "Приклад getComputedStyle",
      category: "DOM",
      textForSearch: "Приклад отримання обчислених стилів елемента.",
      jsx: (
        <ButtonExampleWithBtn
          titleButtonExample={"Приклад getComputedStyle"}
          title={
            <p id="formated-text">
              <div
                className="getStyle"
                style={{ fontSize: "20px", color: "blue" }}
              >
                Text
              </div>
              <div className="getStyle1"></div>
            </p>
          }
          text={
            <pre>
              <code>{getComputedStyle}</code>
            </pre>
          }
          onClick={getStyle}
        />
      ),
    },
  ];

  const filteredData = tableData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredData.length > 0 && (
        <Table id="dom_changeProperties">
          <TableBody>
            <TableOneCol text={<h3>Зміна властивостей елементів HTML.</h3>} />
            {filteredData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
