import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function TextUA({ searchTerm }: IMethodsProps) {
  const textData = [
    {
      title: "Текстовий зміст",
      category: "HTML",
      textForSearch:
        "Текстовий зміст, <blockquote>, <div>, <dd>, <dl>, <dt>, <figcaption>, <figure>, <hr>, <menu>, <p>, <pre>, <ul>, <ol>, <li>.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Використовуйте текстові елементи HTML для організації блоків або
                розділів вмісту, розміщених між тегами відкриття &lt;body&gt; і
                закриття &lt;/body&gt;. Важливо для
                <b>доступності</b> та <b>SEO</b>, щоб ці елементи визначали мету
                або структуру цього контенту.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "<blockquote>",
      category: "HTML",
      textForSearch: "<blockquote>, цитати, цитування.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;blockquote&gt; &lt;/blockquote&gt;</h3>}
          text={<p>Для створення цитат.</p>}
        />
      ),
    },
    {
      title: "<div>",
      category: "HTML",
      textForSearch: "<div>, універсальний контейнер, div.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;div&gt; &lt;/div&gt;</h3>}
          text={
            <p>
              Є універсальним контейнером для потокового контенту. Він не
              впливає на контент або макет доти, доки не буде стилізований за
              допомогою CSS.
            </p>
          }
        />
      ),
    },
    {
      title: "<dd>",
      category: "HTML",
      textForSearch: "<dd>, визначення в списку, опис терміну.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;dd&gt; &lt;/dd&gt;</h3>}
          text={
            <p>
              Надає подробиці або визначення попереднього терміну &lt;dt&gt; у
              списку визначень &lt;dl&gt;.
            </p>
          }
        />
      ),
    },
    {
      title: "<dl>",
      category: "HTML",
      textForSearch: "<dl>, список визначень, глосарій, пари ключ-значення.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;dl&gt; &lt;/dl&gt;</h3>}
          text={
            <p>
              Являє собою перелік описів. Цей елемент служить контейнером для
              списку пар термінів (визначуваних елементом &lt;dt&gt;) та їх
              описів (визначаються елементами &lt;dd&gt;). Цей елемент зазвичай
              використовують при створенні глосарію або для відображення
              метаданих (списку пар ключ-значення).
            </p>
          }
        />
      ),
    },
    {
      title: "<dt>",
      category: "HTML",
      textForSearch: "<dt>, термін у списку визначень.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;dt&gt; &lt;/dt&gt;</h3>}
          text={
            <p>
              Визначає термін в описі або списку визначень, як такий повинен
              використовуватися всередині елемента &lt;dl&gt;.
            </p>
          }
        />
      ),
    },
    {
      title: "<figcaption>",
      category: "HTML",
      textForSearch: "<figcaption>, заголовок ілюстрації, підпис малюнка.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;figcaption&gt; &lt;/figcaption&gt;</h3>}
          text={
            <p>
              Для створення заголовка ілюстрації використовується з елементом
              &lt;figure&gt;.
            </p>
          }
        />
      ),
    },
    {
      title: "<figure>",
      category: "HTML",
      textForSearch: "<figure>, ілюстрація, малюнок з підписом.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;figure&gt; &lt;/figure&gt;</h3>}
          text={
            <p>
              Ілюстрація з необов'язковим підписом представляє самостійний
              контент, який вказується за допомогою елемента &lt;figcaption&gt;.
            </p>
          }
        />
      ),
    },
    {
      title: "<hr>",
      category: "HTML",
      textForSearch: "<hr>, горизонтальна лінія, розділювач.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;hr /&gt;</h3>}
          text={
            <p>
              Елемент служить для тематичного поділу абзаців. Малює
              горизонтальну пряму.
            </p>
          }
        />
      ),
    },
    {
      title: "<menu>",
      category: "HTML",
      textForSearch: "<menu>, меню, список команд.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;menu&gt; &lt;/menu&gt;</h3>}
          text={
            <p>
              Представляє групу команд, які користувач може виконати чи
              активувати. Він включає як меню-списки, які можуть відображатися у
              верхній частині екрана, так і контекстні меню, наприклад, такі, що
              можуть з'явитися під кнопкою після натискання.
            </p>
          }
        />
      ),
    },
    {
      title: "<p>",
      category: "HTML",
      textForSearch: "<p>, абзац тексту, параграф.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;p&gt; &lt;/p&gt;</h3>}
          text={<p>Являє собою абзац.</p>}
        />
      ),
    },
    {
      title: "<pre>",
      category: "HTML",
      textForSearch: "<pre>, попередньо відформатований текст.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;pre&gt; &lt;/pre&gt;</h3>}
          text={
            <p>
              Це попередньо відформатований текст, який повинен бути
              представлений точно так, як написано в HTML-файлі.
            </p>
          }
        />
      ),
    },
    {
      title: "<ul>",
      category: "HTML",
      textForSearch: "<ul>, невпорядкований список, маркований список.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;ul&gt; &lt;/ul&gt;</h3>}
          text={
            <p>
              Використовується для невпорядкованого списку, зокрема для
              маркованого списку.
            </p>
          }
        />
      ),
    },
    {
      title: "<ol>",
      category: "HTML",
      textForSearch: "<ol>, впорядкований список, нумерований список.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;ol&gt; &lt;/ol&gt;</h3>}
          text={
            <p>
              Використовується для впорядкованого списку, зокрема, для
              пронумерованого списку.
            </p>
          }
        />
      ),
    },
    {
      title: "<li>",
      category: "HTML",
      textForSearch: "<li>, елемент списку.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;li&gt; &lt;/li&gt;</h3>}
          text={<p>Використовується для створення елементів списку.</p>}
        />
      ),
    },
  ];

  const filteredTextData = textData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );
  return (
    <>
      {filteredTextData.length > 0 && (
        <Table id="html_text">
          <TableBody>
            <TableOneCol text={<h2>Текстовий зміст.</h2>} />
            {filteredTextData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
