import React, { useState, useEffect, useRef } from "react";
import Container from "@mui/material/Container";
import TableContainer from "@mui/material/TableContainer";
import Button from "@mui/material/IconButton";
import Arrow from "../../core/Arrow";
import MenuDom from "./MenuDom.tsx";
import "./dom.scss";
import DomModelRU from "./DomModelRU.tsx";
import DomFindElementsRU from "./DomFindElementsRU.tsx";
import ChangePropertiesRU from "./ChangePropertiesRU.tsx";
import AttributesClassRU from "./AttributesClassRU.tsx";
import CreatingNodesRU from "./CreatingNodesRU.tsx";
import ElementsRU from "./ElementsRU.tsx";
import ListenerRU from "./ListenerRU.tsx";
import EventRU from "./EventRU.tsx";
import AppBar from "../AppBar.tsx";

export default function DomRU() {
  const [isMenuInfoOpen, setIsMenuInfoOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const menuRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  const handleMenuInfoOpen = () => {
    setIsMenuInfoOpen(!isMenuInfoOpen);
  };

  const handleMenuInfoClose = () => {
    setIsMenuInfoOpen(false);
  };

  useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      if (
        isMenuInfoOpen &&
        menuRef.current &&
        !menuRef.current.contains(event.target as Node) &&
        buttonRef.current &&
        !buttonRef.current.contains(event.target as Node)
      ) {
        setIsMenuInfoOpen(false);
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);

    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
    };
  }, [isMenuInfoOpen]);

  const handleSearch = (term) => {
    setSearchTerm(term);
  };
  return (
    <>
      <AppBar
        onSearch={handleSearch}
        classLangUA={"buttonLanguages"}
        toUA={"/dom/ua"}
        titleLangUA={"UA"}
        classLangRU={"buttonLanguages active"}
        toRU={"/dom/ru"}
        titleLangRU={"RU"}
        toHome={"/home/ru"}
        toHtml={"/html/ru"}
        toCss={"/css/ru"}
        toScss={"/scss/ru"}
        toJS={"/js/ru"}
        toDom={"/dom/ru"}
        toBom={"/bom/ru"}
        toHttp={"/http/ru"}
        toReact={"/react/ru"}
        toRedux={"/redux/ru"}
        toTS={"/ts/ru"}
        toNext={"/next/ru"}
        nameHome={"Главная страница"}
        nameHtml={"HTML5"}
        nameCss={"CSS"}
        nameScss={"SCSS"}
        nameJS={"JavaScript"}
        nameDom={"DOM"}
        nameBom={"BOM"}
        nameHttp={"HTTP"}
        nameReact={"React"}
        nameRedux={"Redux"}
        nameTS={"TypeScript"}
        nameNext={"NextJS"}
      />
      <Container style={{ width: "100%", maxWidth: "none" }}>
        <Button
          id="menu-btnInfo"
          aria-label="open drawer"
          onClick={handleMenuInfoOpen}
          ref={buttonRef}
        >
          DOM
        </Button>
        {isMenuInfoOpen && (
          <div ref={menuRef}>
            <MenuDom
              sectionFirst={"DOM"}
              sectionSecond={"Поиск элементов"}
              sectionThird={"Изменение свойств элементов HTML"}
              sectionFourth={"Атрибуты"}
              sectionFifth={"Классы"}
              sectionSixth={"Методы для создания узлов"}
              sectionSeventh={"Добавление и удаление элементов"}
              sectionEighth={"Клонирование элементов"}
              sectionNinth={"Обработчик"}
              sectionTenth={"Делегирование событий"}
              sectionEleventh={"События мыши"}
              sectionTwelfth={"События на элементах управления"}
              sectionThirteenth={"События фокуса"}
              sectionFourteenth={"Клавиатурные события"}
              sectionFifteenth={"CSS events"}
              sectionSixteenth={"События журнала сессии"}
              sectionSeventeenth={"События Text Composition"}
              sectionEighteenth={"События печати"}
              sectionNineteenth={"События ресурса"}
              sectionTwentieth={"Сетевые события"}
              sectionTwentyFirst={"События веб-сокетов"}
              sectionTwentySecond={"События представления"}
              sectionTwentyThird={"События буфера обмена"}
              sectionTwentyFourth={"События Drag & Drop"}
              onClose={handleMenuInfoClose}
            />
          </div>
        )}
        <TableContainer>
          <DomModelRU searchTerm={searchTerm} />
          <DomFindElementsRU searchTerm={searchTerm} />
          <ChangePropertiesRU searchTerm={searchTerm} />
          <AttributesClassRU searchTerm={searchTerm} />
          <CreatingNodesRU searchTerm={searchTerm} />
          <ElementsRU searchTerm={searchTerm} />
          <ListenerRU searchTerm={searchTerm} />
          <EventRU searchTerm={searchTerm} />
        </TableContainer>
        <footer className="footer">
          <a
            target="_blank"
            href="https://developer.mozilla.org/ru/docs/Web/API/Document_Object_Model"
          >
            Документация DOM
          </a>
        </footer>
      </Container>
      <Arrow />
    </>
  );
}
