import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import ButtonExample from "../../core/ButtonExample.tsx";
import { IMethodsProps } from "../../types/interface.ts";
import "./background.scss";
import { blendMode, clipBB, clipPB, clipCB, clipT } from "./CssConstPre.tsx";

export default function BackgroundRU({ searchTerm }: IMethodsProps) {
  const tableBackground = [
    {
      title: "background",
      category: "Фон",
      textForSearch: "Сокращенная форма для всех свойств фона.",
      jsx: (
        <TableTwoCol
          title={<h3>background:</h3>}
          text={<p>Сокращённая форма для всех свойств фона.</p>}
        />
      ),
    },
    {
      title: "background-attachment",
      category: "Фон",
      textForSearch:
        "Устанавливает, будет ли фоновое изображение прокручиваться вместе с содержимым элемента.",
      jsx: (
        <TableTwoCol
          title={<h3>background-attachment:</h3>}
          text={
            <p>
              Устанавливает, будет ли прокручиваться фоновое изображение вместе
              с содержимым элемента.
            </p>
          }
        />
      ),
    },
    {
      title: "background-blend-mode",
      category: "Фон",
      textForSearch: "Позволяет наложить одно фоновое изображение на другое.",
      jsx: (
        <TableTwoCol
          title={<h3>background-blend-mode:</h3>}
          text={<p>Позволяет наложить одно фоновое изображение на другое.</p>}
        />
      ),
    },
    {
      title: "Пример blend-mode",
      textForSearch: "Пример blend-mode.",
      jsx: (
        <ButtonExample
          titleButtonExample={"Пример blend-mode"}
          title={
            <p id="formated-text">
              <div className="blend-mode"></div>
            </p>
          }
          text={
            <pre>
              <code>{blendMode}</code>
            </pre>
          }
        />
      ),
    },
    {
      title: "background-clip",
      category: "Фон",
      textForSearch:
        "Определяет,  как фон элемента будет отображаться в зависимости от его области. Оно позволяет контролировать, где именно фон будет виден: в пределах содержимого, внутренней области (с учетом отступов) или границы элемента.",
      jsx: (
        <TableTwoCol
          title={<h3>background-clip:</h3>}
          text={
            <p>
              Определяет, как фон элемента будет отображаться в зависимости от
              его области. Оно позволяет контролировать, где именно фон будет
              виден: в пределах содержимого, внутренней области (с учетом
              отступов) или границы элемента.
            </p>
          }
        />
      ),
    },
    {
      title: "Пример clip",
      textForSearch: "Пример clip.",
      jsx: (
        <>
          <ButtonExample
            titleButtonExample={"Пример clip border-box"}
            title={
              <p id="formated-text">
                <div className="clipBB">clip border-box</div>
              </p>
            }
            text={
              <pre>
                <code>{clipBB}</code>
              </pre>
            }
          />
          <ButtonExample
            titleButtonExample={"Пример clip padding-box"}
            title={
              <p id="formated-text">
                <div className="clipPB">clip padding-box</div>
              </p>
            }
            text={
              <pre>
                <code>{clipPB}</code>
              </pre>
            }
          />
          <ButtonExample
            titleButtonExample={"Пример clip content-box"}
            title={
              <p id="formated-text">
                <div className="clipCB">clip content-box</div>
              </p>
            }
            text={
              <pre>
                <code>{clipCB}</code>
              </pre>
            }
          />
          <ButtonExample
            titleButtonExample={"Пример clip text"}
            title={
              <p id="formated-text">
                <div className="clipT">clip text</div>
              </p>
            }
            text={
              <pre>
                <code>{clipT}</code>
              </pre>
            }
          />
        </>
      ),
    },

    {
      title: "background-color",
      category: "Фон",
      textForSearch: "Позволяет задать цвет фона.",
      jsx: (
        <TableTwoCol
          title={<h3>background-color:</h3>}
          text={<p>Позволяет задать цвет фона.</p>}
        />
      ),
    },
    {
      title: "background-image",
      category: "Фон",
      textForSearch: "Позволяет вставить фоновое изображение.",
      jsx: (
        <TableTwoCol
          title={<h3>background-image:</h3>}
          text={<p>Позволяет вставить фоновое изображение.</p>}
        />
      ),
    },
    {
      title: "background-origin",
      category: "Фон",
      textForSearch:
        "Определяет область позиционирования фонового рисунка. Не применяется, если background-attachment: fixed.",
      jsx: (
        <TableTwoCol
          title={<h3>background-origin:</h3>}
          text={
            <p>
              Определяет область позиционирования фонового рисунка. Это свойство
              не применяется, когда значение `background-attachment` задано как
              `fixed`.
            </p>
          }
        />
      ),
    },
    {
      title: "background-position-x",
      category: "Фон",
      textForSearch: "Задает положение фонового изображения по горизонтали.",
      jsx: (
        <TableTwoCol
          title={<h3>background-position-x:</h3>}
          text={
            <p>
              Задает положение фонового изображения внутри элемента по
              горизонтали. <br />
              background-position-x: top; <br />
              background-position-y: center;
            </p>
          }
        />
      ),
    },
    {
      title: "background-position-y",
      category: "Фон",
      textForSearch: "Задает положение фонового изображения по вертикали.",
      jsx: (
        <TableTwoCol
          title={<h3>background-position-y:</h3>}
          text={
            <p>
              Задает положение фонового изображения внутри элемента по
              вертикали. <br />
              background-position-x: center; <br />
              background-position-y: top;
            </p>
          }
        />
      ),
    },
    {
      title: "background-position",
      category: "Фон",
      textForSearch: "Позволяет менять позицию фонового изображения.",
      jsx: (
        <TableTwoCol
          title={<h3>background-position:</h3>}
          text={
            <p>
              Позволяет менять позицию фонового изображения. <br />
              background-position: top left; <br />
              background-position: center; <br />
              background-position: 50% 50%;
            </p>
          }
        />
      ),
    },
    {
      title: "background-repeat",
      category: "Фон",
      textForSearch:
        "Позволяет отключить или включить повторение фонового изображения.",
      jsx: (
        <TableTwoCol
          title={<h3>background-repeat:</h3>}
          text={
            <p>
              Позволяет отключить или подключить повторение фонового
              изображения. <br />
              repeat (по умолчанию): Фоновое изображение будет повторяться как
              по горизонтали, так и по вертикали. <br />
              repeat-x: Фоновое изображение будет повторяться только по
              горизонтали. <br />
              repeat-y: Фоновое изображение будет повторяться только по
              вертикали. <br />
              no-repeat: Фоновое изображение не будет повторяться и отобразится
              только один раз. <br />
              space: Фоновое изображение будет повторяться, но оставшиеся
              пространства между изображениями будут равномерно распределены.
              <br />
              round: Фоновое изображение будет повторяться, и его размеры будут
              уменьшены, чтобы вписаться в элемент, сохраняя при этом пропорции.
            </p>
          }
        />
      ),
    },
    {
      title: "background-size",
      category: "Фон",
      textForSearch: "Позволяет изменить размер фонового изображения.",
      jsx: (
        <TableTwoCol
          title={<h3>background-size:</h3>}
          text={<p>Позволяет изменить размер фонового изображения.</p>}
        />
      ),
    },
    {
      title: "box-decoration-break",
      category: "Оформление",
      textForSearch:
        "Указывает, как оформлять фрагмент текста при его переносе. slice, clone.",
      jsx: (
        <TableTwoCol
          title={<h3>box-decoration-break:</h3>}
          text={
            <p>
              Указывает, как оформлять фрагмент текста при его переносе на
              другую строку. Работает только для следующих свойств:
              `background`, `border`, `border-image`, `box-shadow`, `clip-path`,
              `margin` и `padding`.
              <br />
              **slice** - каждый фрагмент разрезается в месте переноса.
              <br />
              **clone** - каждый фрагмент оформляется независимо.
            </p>
          }
        />
      ),
    },
    {
      title: "box-shadow",
      category: "Оформление",
      textForSearch: "Позволяет создать тень для объекта.",
      jsx: (
        <TableTwoCol
          title={<h3>box-shadow:</h3>}
          text={
            <p>
              Позволяет создать тень для объекта. <br />
              box-shadow: 5px 5px 10px gray; <br />
              box-shadow: 5px 5px 10px 2px rgba(0, 0, 0, 0.5); <br />
              box-shadow: inset 5px 5px 10px rgba(0, 0, 0, 0.5);
            </p>
          }
        />
      ),
    },
    {
      title: "box-sizing",
      category: "Размеры",
      textForSearch:
        "Изменяет алгоритм расчёта размеров блока. content-box, border-box.",
      jsx: (
        <TableTwoCol
          title={<h3>box-sizing:</h3>}
          text={
            <p>
              Позволяет изменить алгоритм, чтобы свойства `width` и `height`
              задавали размеры блока.
              <br />
              **content-box** - `width` и `height` задают ширину и высоту
              содержимого, не включая `padding` и `border`. <br />
              **border-box** - `width` и `height` включают в себя значения
              `padding` и `border`, но не `margin`.
            </p>
          }
        />
      ),
    },
    {
      title: "accent-color",
      category: "Цвет",
      textForSearch:
        "Применяется для замены цвета фона в элементах управления (checkbox, radio, range).",
      jsx: (
        <TableTwoCol
          title={<h3>accent-color:</h3>}
          text={
            <p>
              Применяется для замены цвета фона в элементах управления
              (`checkbox`, `radio`, `range`).
            </p>
          }
        />
      ),
    },
    {
      title: "isolation",
      category: "Слой",
      textForSearch:
        "Определяет, должен ли элемент создавать новый контекст наложения.",
      jsx: (
        <TableTwoCol
          title={<h3>isolation:</h3>}
          text={
            <p>
              Определяет, должен ли элемент создавать новый контекст наложения.
              Это свойство особенно полезно при использовании совместно с
              `background-blend-mode`.
            </p>
          }
        />
      ),
    },
  ];

  const filteredBackground = tableBackground.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredBackground.length > 0 && (
        <Table id="css_background">
          <TableBody>
            <TableOneCol text={<h2>Работа с фоном.</h2>} />
            <TableOneCol text={<h3>Background - Фон.</h3>} />
            {filteredBackground.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
