import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoEqualCol from "../../core/TableTwoEqualCol.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function ImportRU({ searchTerm }: IMethodsProps) {
  const scssImportData = [
    {
      title: "Директива @import",
      category: "SCSS",
      textForSearch: "@import.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Для подключения одного SCSS-файла к другому используется
                директива @import. Это позволяет разделить код на модули, что
                делает его более организованным и удобным для поддержки. При
                компиляции SCSS-файлов все @import директивы будут заменены
                содержимым соответствующих файлов, в результате чего будет
                создан один большой CSS-файл.
                <br />
                Компилятор ищет другие файлы sass в текущей папке и каталоге
                файлов sass. Дополнительные каталоги поиска можно задавать с
                помощью опции `:load_paths` или `--load-path` в командном
                строки. <br />
                @import ищет Sass-файлы, но есть несколько правил, по которым
                @import работает как CSS-правило:
                <br />
                Если расширение .css <br />
                Если имя файла начинается с http://
                <br />
                Если имя файла вызывается через url()
                <br />
                Если правило @import содержит любые медиазапросы <br />
                Если ни одно из вышеперечисленных условий не соблюдено, а
                расширение файлов .scss или .sass, то эти файлы будут
                импортированы. Если расширение файлов не указано, то Sass
                попытается найти файлы по именем с расширением .scss или .sass и
                импортирует их. Например:
              </p>
            }
          />
          <TableTwoEqualCol
            title={
              <p>
                scss <br />
                <br />
                @import "foo.css"; <br />
                @import "foo" screen; <br />
                @import "http://foo.com/bar"; <br />
                @import url(foo);
              </p>
            }
            text={
              <p>
                css <br />
                <br />
                @import "foo.css"; <br />
                @import "foo" screen; <br />
                @import "http://foo.com/bar"; <br />
                @import url(foo);
              </p>
            }
          />
        </>
      ),
    },
  ];

  const filteredScssImportData = scssImportData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredScssImportData.length > 0 && (
        <Table id="scss_import">
          <TableBody>
            <TableOneCol text={<h2>Директивы.</h2>} />
            <TableOneCol text={<h3>@import</h3>} />
            {filteredScssImportData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
