import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoEqualCol from "../../core/TableTwoEqualCol.tsx";
import {
  mediaOne,
  mediaTwo,
  mediaThree,
  mediaFour,
  mediaFive,
  mediaSix,
} from "./ScssConstPre.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function MediaRU({ searchTerm }: IMethodsProps) {
  const scssMediaData = [
    {
      title: "Директива @media",
      category: "SCSS",
      textForSearch: "@media.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Директива <b>@media</b> работает так же, как и стандартное
                правило CSS, но с дополнительными возможностями: она может
                вкладываться в правила CSS. При компиляции вложенная директива
                будет поднята вверх таблицы стилей, а селекторы переместятся
                внутрь <b>@media</b>. Это позволяет легко добавлять правила без
                повторения селекторов. Например:
              </p>
            }
          />
          <TableTwoEqualCol
            title={
              <p>
                <pre>{mediaOne}</pre>
              </p>
            }
            text={
              <p>
                <pre>{mediaTwo}</pre>
              </p>
            }
          />
          <TableOneCol
            text={
              <p>
                Запросы могут вкладываться друг в друга. После компиляции они
                будут объединены оператором <b>and</b>.
              </p>
            }
          />
          <TableTwoEqualCol
            title={
              <p>
                <pre>{mediaThree}</pre>
              </p>
            }
            text={
              <p>
                <pre>{mediaFour}</pre>
              </p>
            }
          />
          <TableOneCol
            text={
              <p>
                <b>@media</b> запросы могут содержать в себе все возможности{" "}
                <b>SassScript</b> (включая переменные, функции и операторы) в
                именах компонентов и значениях.
              </p>
            }
          />
          <TableTwoEqualCol
            title={
              <p>
                <pre>{mediaFive}</pre>
              </p>
            }
            text={
              <p>
                <pre>{mediaSix}</pre>
              </p>
            }
          />
        </>
      ),
    },
  ];

  const filteredScssMediaData = scssMediaData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredScssMediaData.length > 0 && (
        <Table id="scss_media">
          <TableBody>
            <TableOneCol text={<h3>@media</h3>} />
            {filteredScssMediaData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
