import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import ButtonExampleWithBtn from "../../core/ButtonExampleWithBtn.tsx";
import { addElemets } from "./DomConstPre.tsx";
import { addElemetsFn } from "./DomFunc.js";
import { IMethodsProps } from "../../types/interface.ts";

export default function ElementsRU({ searchTerm }: IMethodsProps) {
  const tableCreate = [
    {
      title: ".append()",
      category: "DOM",
      textForSearch: "Добавление в конец.",
      jsx: (
        <TableTwoCol
          title={<h3>.append()</h3>}
          text={<p>Добавляет узлы или строки в конец выбранного тега.</p>}
        />
      ),
    },
    {
      title: ".prepend()",
      category: "DOM",
      textForSearch: "Добавление в начало.",
      jsx: (
        <TableTwoCol
          title={<h3>.prepend()</h3>}
          text={<p>Вставляет узлы или строки в начало выбранного тега.</p>}
        />
      ),
    },
    {
      title: ".before()",
      category: "DOM",
      textForSearch: "Вставка до элемента.",
      jsx: (
        <TableTwoCol
          title={<h3>.before()</h3>}
          text={<p>Вставляет узлы или строки до выбранного тега.</p>}
        />
      ),
    },
    {
      title: ".after()",
      category: "DOM",
      textForSearch: "Вставка после элемента.",
      jsx: (
        <TableTwoCol
          title={<h3>.after()</h3>}
          text={<p>Вставляет узлы или строки после выбранного тега.</p>}
        />
      ),
    },
    {
      title: ".replaceWith()",
      category: "DOM",
      textForSearch: "Замена элемента.",
      jsx: (
        <TableTwoCol
          title={<h3>.replaceWith()</h3>}
          text={<p>Заменяет выбранный тег заданными узлами или строками.</p>}
        />
      ),
    },
    {
      title: "Пример добавления элементов",
      category: "DOM",
      textForSearch:
        "Пример добавления, append, prepend, before, after, replaceWith.",
      jsx: (
        <ButtonExampleWithBtn
          titleButtonExample={"Пример"}
          title={
            <p id="formated-text">
              <div className="list_ol">
                <ol id="list_ol">
                  <li>0</li>
                  <li>1</li>
                  <li>2</li>
                </ol>
              </div>
            </p>
          }
          text={
            <pre>
              <code>{addElemets}</code>
            </pre>
          }
          onClick={addElemetsFn}
        />
      ),
    },
  ];

  const tableCloneNode = [
    {
      title: ".cloneNode(deep)",
      category: "DOM",
      textForSearch: "Клонирование с дочерними элементами.",
      jsx: (
        <TableTwoCol
          title={<h3>.cloneNode(deep)</h3>}
          text={
            <p>
              Клонирует элемент, если <b>deep == true</b>, то со всеми дочерними
              элементами.
              <br />
              <code>element.cloneNode(deep)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".cloneNode(true)",
      category: "DOM",
      textForSearch: "Глубокое клонирование.",
      jsx: (
        <TableTwoCol
          title={<h3>.cloneNode(true)</h3>}
          text={
            <p>
              Создаёт «глубокий» клон элемента – со всеми атрибутами и дочерними
              элементами.
              <br />
              <code>element.cloneNode(true)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".cloneNode(false)",
      category: "DOM",
      textForSearch: "Поверхностное клонирование.",
      jsx: (
        <TableTwoCol
          title={<h3>.cloneNode(false)</h3>}
          text={
            <p>
              Клон будет без дочерних элементов.
              <br />
              <code>element.cloneNode(false)</code>
            </p>
          }
        />
      ),
    },
  ];

  const filteredCreate = tableCreate.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredCloneNode = tableCloneNode.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredCreate.length > 0 && (
        <Table id="dom_create">
          <TableBody>
            <TableOneCol text={<h3>Добавление и удаление элементов.</h3>} />
            {filteredCreate.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}

      {filteredCloneNode.length > 0 && (
        <Table id="dom_cloneNode">
          <TableBody>
            <TableOneCol text={<h3>Клонирование элементов.</h3>} />
            {filteredCloneNode.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
