import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function TextRU({ searchTerm }: IMethodsProps) {
  const textData = [
    {
      title: "Текстовое содержание",
      category: "HTML",
      textForSearch:
        "Текстовое содержание, <blockquote>, <div>, <dd>, <dl>, <dt>, <figcaption>, <figure>, <hr>, <menu>, <p>, <pre>, <ul>, <ol>, <li>.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Используйте текстовые элементы HTML для организации блоков или
                разделов содержания, размещённые между тегами открытия
                &lt;body&gt; и закрытия &lt;/body&gt;. Важное значение для
                <b>доступности</b> и <b>SEO</b>, чтобы эти элементы определили
                цель или структуру этого контента.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "<blockquote>",
      category: "HTML",
      textForSearch: "<blockquote>, цитаты, цитирование.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;blockquote&gt; &lt;/blockquote&gt;</h3>}
          text={<p>Для создания цитат.</p>}
        />
      ),
    },
    {
      title: "<div>",
      category: "HTML",
      textForSearch: "<div>, универсальный контейнер, div.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;div&gt; &lt;/div&gt;</h3>}
          text={
            <p>
              Является универсальным контейнером для потокового контента. Он не
              влияет на контент или макет до тех пор, пока не будет стилизован с
              помощью CSS.
            </p>
          }
        />
      ),
    },
    {
      title: "<dd>",
      category: "HTML",
      textForSearch: "<dd>, определение в списке, описание термина.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;dd&gt; &lt;/dd&gt;</h3>}
          text={
            <p>
              Предоставляет подробности или определение предшествующего термина
              &lt;dt&gt; в списке определений &lt;dl&gt;.
            </p>
          }
        />
      ),
    },
    {
      title: "<dl>",
      category: "HTML",
      textForSearch: "<dl>, список определений, глоссарий, пары ключ-значение.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;dl&gt; &lt;/dl&gt;</h3>}
          text={
            <p>
              Представляет собой список описаний. Этот элемент служит
              контейнером для списка пар терминов (определяемых элементом
              &lt;dt&gt;) и их описаний (определяемых элементами &lt;dd&gt;).
              Этот элемент обычно используют при создании глоссария или для
              отображения метаданных (списка пар ключ-значение).
            </p>
          }
        />
      ),
    },
    {
      title: "<dt>",
      category: "HTML",
      textForSearch: "<dt>, термин в списке определений.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;dt&gt; &lt;/dt&gt;</h3>}
          text={
            <p>
              Определяет термин в описании или списке определений, как таковой
              должен использоваться внутри элемента &lt;dl&gt;.
            </p>
          }
        />
      ),
    },
    {
      title: "<figcaption>",
      category: "HTML",
      textForSearch: "<figcaption>, заголовок иллюстрации, подпись рисунка.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;figcaption&gt; &lt;/figcaption&gt;</h3>}
          text={
            <p>
              Для создания заголовка иллюстрации используется с элементом
              &lt;figure&gt;.
            </p>
          }
        />
      ),
    },
    {
      title: "<figure>",
      category: "HTML",
      textForSearch: "<figure>, иллюстрация, рисунок с подписью.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;figure&gt; &lt;/figure&gt;</h3>}
          text={
            <p>
              Иллюстрация с необязательной подписью представляет самостоятельный
              контент, которая указывается с помощью элемента
              &lt;figcaption&gt;.
            </p>
          }
        />
      ),
    },
    {
      title: "<hr>",
      category: "HTML",
      textForSearch: "<hr>, горизонтальная линия, разделитель.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;hr /&gt;</h3>}
          text={
            <p>
              Элемент служит для тематического разделения абзацев. Рисует
              горизонтальную прямую.
            </p>
          }
        />
      ),
    },
    {
      title: "<menu>",
      category: "HTML",
      textForSearch: "<menu>, меню, список команд.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;menu&gt; &lt;/menu&gt;</h3>}
          text={
            <p>
              Представляет группу команд, которые пользователь может выполнить
              или активировать. Он включает как меню-списки, которые могут
              отображаться в верхней части экрана, так и контекстные меню,
              например, такие, что могут появиться под кнопкой после нажатия.
            </p>
          }
        />
      ),
    },
    {
      title: "<p>",
      category: "HTML",
      textForSearch: "<p>, абзац текста, параграф.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;p&gt; &lt;/p&gt;</h3>}
          text={<p>Представляет собой абзац.</p>}
        />
      ),
    },
    {
      title: "<pre>",
      category: "HTML",
      textForSearch: "<pre>, предварительно отформатированный текст.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;pre&gt; &lt;/pre&gt;</h3>}
          text={
            <p>
              Представляет собой предварительно отформатированный текст, который
              должен быть представлен точно так, как написано в HTML-файле.
            </p>
          }
        />
      ),
    },
    {
      title: "<ul>",
      category: "HTML",
      textForSearch: "<ul>, неупорядоченный список, маркированный список.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;ul&gt; &lt;/ul&gt;</h3>}
          text={
            <p>
              Используется для неупорядоченного списка — в частности для
              маркированного списка.
            </p>
          }
        />
      ),
    },
    {
      title: "<ol>",
      category: "HTML",
      textForSearch: "<ol>, упорядоченный список, нумерованный список.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;ol&gt; &lt;/ol&gt;</h3>}
          text={
            <p>
              Используется для упорядоченного списка — в частности для
              пронумерованного списка.
            </p>
          }
        />
      ),
    },
    {
      title: "<li>",
      category: "HTML",
      textForSearch: "<li>, элемент списка.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;li&gt; &lt;/li&gt;</h3>}
          text={<p>Используется для создания элементов списка.</p>}
        />
      ),
    },
  ];

  const filteredTextData = textData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredTextData.length > 0 && (
        <Table id="html_text">
          <TableBody>
            <TableOneCol text={<h2>Текстовое содержание.</h2>} />
            {filteredTextData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
