import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function HtmlTitleRU({ searchTerm }: IMethodsProps) {
  const tableTitle = [
    {
      title: "Работа с HTML",
      category: "HTML",
      textForSearch: "Работа с HTML, основные элементы HTML.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Основные элементы являются основой любого HTML документа. Вы
                увидите эти элементы в исходном коде для всех веб-страниц после
                задания типа документа на первой строке на странице.
                <b>DOCTYPE</b> определяет, какую версию (X) HTML эта страница
                использует. Элементы страницы находятся между открывающим и
                закрывающим тегом &lt;html&gt; &lt;/html&gt;. Элемент
                &lt;html&gt; называется корневым элементом.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "<html>",
      category: "HTML",
      textForSearch: "<html>, корневой элемент HTML.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;html&gt; &lt;/html&gt;</h3>}
          text={
            <p>
              Представляет собой корень (элемент верхнего уровня)
              HTML-документа, поэтому его так же называют{" "}
              <b>корневым элементом</b>. Все другие элементы должны быть
              потомками этого элемента (должны находиться внутри него).
            </p>
          }
        />
      ),
    },
  ];

  const filteredTitle = tableTitle.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredTitle.length > 0 && (
        <Table id="html-title">
          <TableBody>
            <TableOneCol text={<h1>Работа с HTML.</h1>} />
            <TableOneCol text={<h2>Основные элементы</h2>} />
            {filteredTitle.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
