import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import ButtonExampleWithBtn from "../../core/ButtonExampleWithBtn.tsx";
import {
  proxyGetConst,
  proxySetConst,
  proxyHasConst,
  proxydeleteConst,
  proxyApplyConst,
  proxyConstructConst,
  proxyDefinePropertyConst,
  proxyGetOwnConst,
  proxyPrototypeOfConst,
  proxyIsExtensibleConst,
  proxyOwnKeysConst,
  proxyPreventExtensionsConst,
  proxySetPrototypeOfConst,
} from "./ProxyConstPre.ts";
import {
  proxyGet,
  proxySet,
  proxyHas,
  proxydelete,
  proxyApply,
  proxyConstruct,
  proxyDefineProperty,
  proxyGetOwn,
  proxyPrototypeOf,
  proxyIsExtensible,
  proxyOwnKeys,
  proxyPreventExtensions,
  proxySetPrototypeOf,
} from "./proxy.js";
import { IMethodsProps } from "../../types/interface.ts";

export default function ProxyRU({ searchTerm }: IMethodsProps) {
  const tableData = [
    {
      title: "Proxy",
      textForSearch:
        "Прокси это своеобразная обёртка в которую помещаются другие объекты. При этом можно производить различные манипуляции (добавлять, изменять, удалять) с свойствами.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Прокси это своеобразная обёртка в которую помещаются другие
                объекты. При этом можно производить различные манипуляции
                (добавлять, изменять, удалять) с свойствами. <br />
                let proxy = new Proxy(target, handler);
                <br />
                <b>target</b> — объект (массив, функция и т.д.) для которого
                создаётся прокси. <br />
                <b>handler</b> - тут описываются ловушки которые необходимы для
                данного прокси.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "Функции обработчика",
      textForSearch: "Функции обработчика Proxy.",
      jsx: <TableOneCol text={<h3>Функции обработчика.</h3>} />,
    },
    {
      title: ".apply()",
      textForSearch:
        "apply(target, thisArg, argArray) thisArg – это контекст this. argArray – список аргументов.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>.apply()</h3>}
            text={
              <p>
                <b>apply(target, thisArg, argArray)</b> <br />
                <b>thisArg</b> – это контекст this. <br />
                <b>argArray</b> – список аргументов.
              </p>
            }
          />
          <ButtonExampleWithBtn
            titleButtonExample={"Пример Proxy apply"}
            title={
              <p id="formated-text">
                <span id="jsproxyapply"></span>
              </p>
            }
            text={
              <pre>
                <code>{proxyApplyConst}</code>
              </pre>
            }
            onClick={proxyApply}
          />
        </>
      ),
    },
    {
      title: ".construct()",
      textForSearch:
        "construct(target, argumentsList, newTarget) newTarget - конструктор, который был первоначально вызван.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>.construct()</h3>}
            text={
              <p>
                <b>construct(target, argumentsList, newTarget)</b> <br />
                <b>newTarget</b> - конструктор, который был первоначально
                вызван.
              </p>
            }
          />
          <ButtonExampleWithBtn
            titleButtonExample={"Пример Proxy construct"}
            title={
              <p id="formated-text">
                <span id="jsproxyConstruct"></span>
              </p>
            }
            text={
              <pre>
                <code>{proxyConstructConst}</code>
              </pre>
            }
            onClick={proxyConstruct}
          />
        </>
      ),
    },
    {
      title: ".defineProperty()",
      textForSearch:
        "defineProperty(target, property, descriptor) descriptor - дескриптор определяемого или изменяемого свойства.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>.defineProperty()</h3>}
            text={
              <p>
                <b>defineProperty(target, property, descriptor)</b> <br />
                <b>descriptor</b> - дескриптор определяемого или изменяемого
                свойства.
              </p>
            }
          />
          <ButtonExampleWithBtn
            titleButtonExample={"Пример Proxy defineProperty"}
            title={
              <p id="formated-text">
                <span id="jsproxyDefineProperty"></span>
              </p>
            }
            text={
              <pre>
                <code>{proxyDefinePropertyConst}</code>
              </pre>
            }
            onClick={proxyDefineProperty}
          />
        </>
      ),
    },
    {
      title: ".deleteProperty()",
      textForSearch: "Позволяет удалить ненужное свойства.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>.deleteProperty()</h3>}
            text={<p>Позволяет удалить ненужное свойства.</p>}
          />
          <ButtonExampleWithBtn
            titleButtonExample={"Пример Proxy deleteProperty"}
            title={
              <p id="formated-text">
                <span id="jsproxydelete"></span>
              </p>
            }
            text={
              <pre>
                <code>{proxydeleteConst}</code>
              </pre>
            }
            onClick={proxydelete}
          />
        </>
      ),
    },
    {
      title: ".get()",
      textForSearch:
        "Является ловушкой для получения значения свойства. get(target, property, receiver) target – это оригинальный объект, который передавался первым аргументом в конструктор new Proxy. property – имя свойства. receiver – это сам объект прокси (или наследующий от него объект).",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>.get()</h3>}
            text={
              <p>
                Является ловушкой для получения значения свойства. <br />
                <b>get(target, property, receiver)</b> <br />
                <b>target</b> – это оригинальный объект, который передавался
                первым аргументом в конструктор new Proxy. <br />
                <b>property</b> – имя свойства. <br />
                <b>receiver</b> – это сам объект прокси (или наследующий от него
                объект).
              </p>
            }
          />
          <ButtonExampleWithBtn
            titleButtonExample={"Пример Proxy get"}
            title={
              <p id="formated-text">
                <span id="jsproxyGet"></span>
              </p>
            }
            text={
              <pre>
                <code>{proxyGetConst}</code>
              </pre>
            }
            onClick={proxyGet}
          />
        </>
      ),
    },
    {
      title: ".getOwnPropertyDescriptor()",
      textForSearch:
        "Является ловушкой и позволяет просмотреть точное описание свойства состоящего из строкового имени и дескриптора свойства.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>.getOwnPropertyDescriptor()</h3>}
            text={
              <p>
                Является ловушкой и позволяет просмотреть точное описание
                свойства состоящего из строкового имени и дескриптора свойства.
              </p>
            }
          />
          <ButtonExampleWithBtn
            titleButtonExample={"Пример Proxy getOwnPropertyDescriptor"}
            title={
              <p id="formated-text">
                <span id="jsproxyGetOwn"></span>
              </p>
            }
            text={
              <pre>
                <code>{proxyGetOwnConst}</code>
              </pre>
            }
            onClick={proxyGetOwn}
          />
        </>
      ),
    },
    {
      title: ".getPrototypeOf()",
      textForSearch:
        "Является ловушкой способеной вернуть прототип свойств указанного объекта.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>.getPrototypeOf()</h3>}
            text={
              <p>
                Является ловушкой способеной вернуть прототип свойств указанного
                объекта.
              </p>
            }
          />
          <ButtonExampleWithBtn
            titleButtonExample={"Пример Proxy getPrototypeOf"}
            title={
              <p id="formated-text">
                <span id="jsproxyPrototypeOf"></span>
              </p>
            }
            text={
              <pre>
                <code>{proxyPrototypeOfConst}</code>
              </pre>
            }
            onClick={proxyPrototypeOf}
          />
        </>
      ),
    },
    {
      title: ".has()",
      textForSearch:
        "Возвращает булевое значение. Если свойства есть true и false если свойства нет. has(target, property)",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>.has()</h3>}
            text={
              <p>
                Возвращает булевое значение. Если свойства есть true и false
                если свойства нет. <br />
                <b>has(target, property)</b>
              </p>
            }
          />
          <ButtonExampleWithBtn
            titleButtonExample={"Пример Proxy has"}
            title={
              <p id="formated-text">
                <span id="jsproxyHas"></span>
              </p>
            }
            text={
              <pre>
                <code>{proxyHasConst}</code>
              </pre>
            }
            onClick={proxyHas}
          />
        </>
      ),
    },
    {
      title: ".isExtensible()",
      textForSearch:
        "Является ловушкой для isExtensible. Определяет, является ли объект расширяемым (то есть, можно ли к нему добавлять новые свойства).",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>.isExtensible()</h3>}
            text={
              <p>
                Является ловушкой для isExtensible. Определяет, является ли
                объект расширяемым (то есть, можно ли к нему добавлять новые
                свойства).
              </p>
            }
          />
          <ButtonExampleWithBtn
            titleButtonExample={"Пример Proxy isExtensible"}
            title={
              <p id="formated-text">
                <span id="jsproxyIsExtensible"></span>
              </p>
            }
            text={
              <pre>
                <code>{proxyIsExtensibleConst}</code>
              </pre>
            }
            onClick={proxyIsExtensible}
          />
        </>
      ),
    },
    {
      title: ".ownKeys()",
      textForSearch:
        "Возвращает массив всех собственных свойств (не унаследованных) целевого объекта, включая неперечисляемые свойства.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>.ownKeys()</h3>}
            text={
              <p>
                Возвращает массив всех собственных свойств (не унаследованных)
                целевого объекта, включая неперечисляемые свойства.
              </p>
            }
          />
          <ButtonExampleWithBtn
            titleButtonExample={"Пример Proxy ownKeys"}
            title={
              <p id="formated-text">
                <span id="jsproxyOwnKeys"></span>
              </p>
            }
            text={
              <pre>
                <code>{proxyOwnKeysConst}</code>
              </pre>
            }
            onClick={proxyOwnKeys}
          />
        </>
      ),
    },
    {
      title: ".preventExtensions()",
      textForSearch:
        "Метод используется для предотвращения добавления новых свойств к объекту.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>.preventExtensions()</h3>}
            text={
              <p>
                Метод используется для предотвращения добавления новых свойств к
                объекту. Когда этот метод вызывается на объекте, он делает
                объект нерасширяемым, что означает, что нельзя добавить новые
                свойства к объекту.
              </p>
            }
          />
          <ButtonExampleWithBtn
            titleButtonExample={"Пример Proxy preventExtensions"}
            title={
              <p id="formated-text">
                <span id="jsproxyPreventExtensions"></span>
              </p>
            }
            text={
              <pre>
                <code>{proxyPreventExtensionsConst}</code>
              </pre>
            }
            onClick={proxyPreventExtensions}
          />
        </>
      ),
    },
    {
      title: ".set()",
      textForSearch:
        "Данная ловушка срабатывает когда необходимо написать какое то свойство. set(target, property, value, receiver) target – это оригинальный объект, который передавался первым аргументом в конструктор new Proxy. property – имя свойства. value – значение свойства. receiver – это сам объект прокси (или наследующий от него объект).",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>.set()</h3>}
            text={
              <p>
                Данная ловушка срабатывает когда необходимо написать какое то
                свойство. <br />
                <b>set(target, property, value, receiver)</b> <br />
                <b>target</b> – это оригинальный объект, который передавался
                первым аргументом в конструктор new Proxy. <br />
                <b>property</b> – имя свойства. <br />
                <b>value</b> – значение свойства. <br />
                <b>receiver</b> – это сам объект прокси (или наследующий от него
                объект).
              </p>
            }
          />
          <ButtonExampleWithBtn
            titleButtonExample={"Пример Proxy set"}
            title={
              <p id="formated-text">
                <span id="jsproxySet"></span>
              </p>
            }
            text={
              <pre>
                <code>{proxySetConst}</code>
              </pre>
            }
            onClick={proxySet}
          />
        </>
      ),
    },
    {
      title: ".setPrototypeOf()",
      textForSearch:
        "Это функция JavaScript, которая используется для установки прототипа (прототипного объекта) для указанного объекта.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>.setPrototypeOf()</h3>}
            text={
              <p>
                Это функция JavaScript, которая используется для установки
                прототипа (прототипного объекта) для указанного объекта.
              </p>
            }
          />
          <ButtonExampleWithBtn
            titleButtonExample={"Пример Proxy setPrototypeOf"}
            title={
              <p id="formated-text">
                <span id="jsproxySetPrototypeOf"></span>
              </p>
            }
            text={
              <pre>
                <code>{proxySetPrototypeOfConst}</code>
              </pre>
            }
            onClick={proxySetPrototypeOf}
          />
        </>
      ),
    },
  ];

  const filteredData = tableData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredData.length > 0 && (
        <Table id="js_proxy">
          <TableBody>
            <TableOneCol text={<h2>Proxy.</h2>} />
            {filteredData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
