import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import { IMethodsProps } from "../../types/interface.ts";

const dom = require("../../images/dom.png");
const domLinks = require("../../images/dom-links.png");
const domLinksElements = require("../../images/dom-links-elements.png");

export default function DomModelRU({ searchTerm }: IMethodsProps) {
  const tableData = [
    {
      title: "Изучение DOM",
      category: "DOM",
      textForSearch:
        "Изучение DOM, Document Object Model, объектная модель документа.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                DOM – это объектная модель документа, которую браузер создаёт в
                памяти компьютера на основании HTML-кода, полученного им от
                сервера. Если сказать по-простому, то HTML-код – это текст
                страницы, а DOM – это набор связанных объектов, созданных
                браузером при парсинге её текста.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "Структура DOM-дерева",
      category: "DOM",
      textForSearch: "Структура DOM, узлы DOM-дерева.",
      jsx: (
        <TableTwoCol
          title={
            <p>
              <img className="dom_images" src={dom} alt="dom" />
            </p>
          }
          text={
            <p>
              Узел <b>html</b> образован элементом <b>&lt;html&gt;</b>. Узлы{" "}
              <b>&lt;head&gt;</b> и <b>&lt;body&gt;</b> имеют родительскую связь
              с <b>&lt;html&gt;</b>. Узел <b>&lt;head&gt;</b> связан с{" "}
              <b>&lt;link&gt;</b>, <b>&lt;meta&gt;</b> и <b>&lt;title&gt;</b> и
              является для них родителем. В свою очередь <b>&lt;body&gt;</b>{" "}
              связан с <b>&lt;header&gt;</b>, <b>&lt;section&gt;</b> и{" "}
              <b>&lt;footer&gt;</b> и является для них родителем. Элемент{" "}
              <b>&lt;section&gt;</b> имеет трёх детей <b>&lt;div&gt;</b>,{" "}
              <b>&lt;p&gt;</b> и <b>&lt;a&gt;</b>.
              <br />
              Не зная как устроено DOM-дерево и связи между узлами, найти
              какой-то определённый элемент в нём будет достаточно
              затруднительно.
            </p>
          }
        />
      ),
    },
    {
      title: "Навигация по DOM-элементам",
      category: "DOM",
      textForSearch: "Навигация DOM, document, childNodes, parentNode.",
      jsx: (
        <>
          <TableOneCol text={<h3>Навигация по DOM-элементам.</h3>} />
          <TableTwoCol
            title={
              <p>
                <img className="dom_images" src={domLinks} alt="dom-links" />
              </p>
            }
            text={
              <p>
                DOM позволяет нам делать что угодно с элементами и их
                содержимым, но для начала нужно получить соответствующий
                DOM-объект.
                <br />
                Все операции с DOM начинаются с объекта <b>document</b>. Это
                главная «точка входа» в DOM. Из него мы можем получить доступ к
                любому узлу. <br />
                Так выглядят основные ссылки, по которым можно переходить между
                узлами DOM.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "document.documentElement",
      category: "DOM",
      textForSearch: "document.documentElement, корневой узел.",
      jsx: (
        <TableTwoCol
          title={<h3>document.documentElement</h3>}
          text={
            <p>
              Самый верхний узел документа, он соответствует тегу{" "}
              <b>&lt;html&gt;</b>.
            </p>
          }
        />
      ),
    },
    {
      title: "document.head",
      category: "DOM",
      textForSearch: "document.head, узел head.",
      jsx: (
        <TableTwoCol
          title={<h3>document.head</h3>}
          text={
            <p>
              Применяется к тегу <b>&lt;head&gt;</b>.
            </p>
          }
        />
      ),
    },
    {
      title: "document.body",
      category: "DOM",
      textForSearch: "document.body, узел body.",
      jsx: (
        <TableTwoCol
          title={<h3>document.body</h3>}
          text={
            <p>
              Другой часто используемый DOM-узел – узел тега <b>&lt;body&gt;</b>
              . Для сокращения кода в дальнейшем используем переменную. <br />
              <code>const bodyElement = document.body;</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".childNodes",
      category: "DOM",
      textForSearch: "childNodes, список дочерних узлов.",
      jsx: (
        <TableTwoCol
          title={<h3>.childNodes</h3>}
          text={
            <p>
              Содержит список всех детей, включая текстовые узлы.
              <br />
              <code>bodyElement.childNodes</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".hasChildNodes",
      category: "DOM",
      textForSearch: "hasChildNodes, проверка наличия дочерних узлов.",
      jsx: (
        <TableTwoCol
          title={<h3>.hasChildNodes</h3>}
          text={
            <p>
              Для проверки, есть ли у элемента дочерние узлы.
              <br />
              <code>bodyElement.hasChildNodes()</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".firstChild",
      category: "DOM",
      textForSearch: "firstChild, первый дочерний узел.",
      jsx: (
        <TableTwoCol
          title={<h3>.firstChild</h3>}
          text={
            <p>
              Обеспечивает быстрый доступ к первому дочернему узлу.
              <br />
              <code>bodyElement.firstChild</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".lastChild",
      category: "DOM",
      textForSearch: "lastChild, последний дочерний узел.",
      jsx: (
        <TableTwoCol
          title={<h3>.lastChild</h3>}
          text={
            <p>
              Обеспечивает быстрый доступ к последнему дочернему узлу.
              <br />
              <code>bodyElement.lastChild</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".previousSibling",
      category: "DOM",
      textForSearch: "previousSibling, предыдущий соседний узел.",
      jsx: (
        <TableTwoCol
          title={<h3>.previousSibling</h3>}
          text={
            <p>
              Предыдущий узел того же родителя.
              <br />
              <code>bodyElement.previousSibling</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".nextSibling",
      category: "DOM",
      textForSearch: "nextSibling, следующий соседний узел.",
      jsx: (
        <TableTwoCol
          title={<h3>.nextSibling</h3>}
          text={
            <p>
              Следующий узел того же родителя.
              <br />
              <code>bodyElement.nextSibling</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".parentNode",
      category: "DOM",
      textForSearch: "parentNode, родительский узел.",
      jsx: (
        <TableTwoCol
          title={<h3>.parentNode</h3>}
          text={
            <p>
              Родитель.
              <br />
              <code>bodyElement.parentNode</code>
            </p>
          }
        />
      ),
    },
    {
      title: "Навигация только по элементам",
      category: "DOM",
      textForSearch:
        "Навигация по элементам, children, firstElementChild, lastElementChild.",
      jsx: (
        <TableTwoCol
          title={
            <p>
              <img
                className="dom_images"
                src={domLinksElements}
                alt="dom-links"
              />
            </p>
          }
          text={
            <p>
              Навигационные свойства, описанные выше, относятся ко всем узлам в
              документе. В частности, в <b>childNodes</b> находятся и текстовые
              узлы, и узлы-элементы, и узлы-комментарии, если они есть.
              <br />
              Но для большинства задач текстовые узлы и узлы-комментарии нам не
              нужны. Мы хотим манипулировать узлами-элементами, которые
              представляют собой теги и формируют структуру страницы.
              <br />
              Поэтому давайте рассмотрим дополнительный набор ссылок, которые
              учитывают только узлы-элементы.
            </p>
          }
        />
      ),
    },
    {
      title: ".children",
      category: "DOM",
      textForSearch: "children, коллекция дочерних элементов.",
      jsx: (
        <TableTwoCol
          title={<h3>.children</h3>}
          text={
            <p>
              Коллекция детей, которые являются элементами.
              <br />
              <code>bodyElement.children</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".firstElementChild",
      category: "DOM",
      textForSearch: "firstElementChild, первый дочерний элемент.",
      jsx: (
        <TableTwoCol
          title={<h3>.firstElementChild</h3>}
          text={
            <p>
              Первый дочерний элемент.
              <br />
              <code>bodyElement.firstElementChild</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".lastElementChild",
      category: "DOM",
      textForSearch: "lastElementChild, последний дочерний элемент.",
      jsx: (
        <TableTwoCol
          title={<h3>.lastElementChild</h3>}
          text={
            <p>
              Последний дочерний элемент.
              <br />
              <code>bodyElement.lastElementChild</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".previousElementSibling",
      category: "DOM",
      textForSearch: "previousElementSibling, предыдущий соседний элемент.",
      jsx: (
        <TableTwoCol
          title={<h3>.previousElementSibling</h3>}
          text={
            <p>
              Предыдущий соседний элемент.
              <br />
              <code>bodyElement.previousElementSibling</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".nextElementSibling",
      category: "DOM",
      textForSearch: "nextElementSibling, следующий соседний элемент.",
      jsx: (
        <TableTwoCol
          title={<h3>.nextElementSibling</h3>}
          text={
            <p>
              Следующий соседний элемент.
              <br />
              <code>bodyElement.nextElementSibling</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".parentElement",
      category: "DOM",
      textForSearch: "parentElement, родительский элемент.",
      jsx: (
        <TableTwoCol
          title={<h3>.parentElement</h3>}
          text={
            <p>
              Родительский элемент. <code>bodyElement.parentElement</code>
            </p>
          }
        />
      ),
    },
  ];

  const filteredData = tableData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredData.length > 0 && (
        <Table id="dom_title">
          <TableBody>
            <TableOneCol text={<h1>Изучение DOM.</h1>} />
            <TableOneCol text={<h2>Document Object Model.</h2>} />
            {filteredData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
