import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import TableTwoEqualCol from "../../core/TableTwoEqualCol.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function TableUA({ searchTerm }: IMethodsProps) {
  const tableData = [
    {
      title: "caption-side",
      category: "CSS",
      textForSearch: "Позиція заголовка таблиці.",
      jsx: (
        <TableTwoCol
          title={<h3>caption-side:</h3>}
          text={
            <p>
              Визначає положення заголовка таблиці, який задається за допомогою
              тега <code>&lt;caption&gt;</code>, щодо самої таблиці.
            </p>
          }
        />
      ),
    },
    {
      title: "columns",
      category: "CSS",
      textForSearch: "Кількість і ширина стовпців.",
      jsx: (
        <TableTwoCol
          title={<h3>columns:</h3>}
          text={
            <p>Встановлює кількість стовпців, а також ширину цих стовпців.</p>
          }
        />
      ),
    },
    {
      title: "column-width",
      category: "CSS",
      textForSearch: "Ширина стовпця.",
      jsx: (
        <TableTwoCol
          title={<h3>column-width:</h3>}
          text={<p>Встановлює ідеальну ширину стовпця.</p>}
        />
      ),
    },
    {
      title: "column-count",
      category: "CSS",
      textForSearch: "Кількість стовпців.",
      jsx: (
        <TableTwoCol
          title={<h3>column-count:</h3>}
          text={<p>Розбиває вміст елемента на задану кількість стовпців.</p>}
        />
      ),
    },
    {
      title: "column-fill",
      category: "CSS",
      textForSearch: "Розподіл вмісту в стовпцях.",
      jsx: (
        <TableTwoCol
          title={<h3>column-fill:</h3>}
          text={
            <p>
              Застосовується до батьківського елемента, розбитого на стовпці та
              вказує як вміст розташовується всередині стовпця.
            </p>
          }
        />
      ),
    },
    {
      title: "column-gap",
      category: "CSS",
      textForSearch: "Проміжок між стовпцями.",
      jsx: (
        <TableTwoCol
          title={<h3>column-gap</h3>}
          text={<p>Встановлює проміжок (інтервал) між колонками.</p>}
        />
      ),
    },
    {
      title: "column-span",
      category: "CSS",
      textForSearch: "Об'єднання елементом кількох стовпців.",
      jsx: (
        <TableTwoCol
          title={<h3>column-span:</h3>}
          text={
            <p>
              Дозволяє елементу охоплювати всі стовпці. Наприклад, для
              заголовка.
            </p>
          }
        />
      ),
    },
    {
      title: "column-rule",
      category: "CSS",
      textForSearch: "Ширина, стиль та колір лінії між стовпцями.",
      jsx: (
        <TableTwoCol
          title={<h3>column-rule:</h3>}
          text={<p>Встановлює ширину, стиль та колір лінії.</p>}
        />
      ),
    },
    {
      title: "column-rule-color",
      category: "CSS",
      textForSearch: "Колір лінії між стовпцями.",
      jsx: (
        <TableTwoCol
          title={<h3>column-rule-color:</h3>}
          text={
            <p>
              Встановлює колір лінії, розташованої між колонками при
              мультиколонній верстці.
            </p>
          }
        />
      ),
    },
    {
      title: "column-rule-style",
      category: "CSS",
      textForSearch: "Стиль лінії між стовпцями.",
      jsx: (
        <TableTwoCol
          title={<h3>column-rule-style:</h3>}
          text={
            <p>
              Встановлює стиль лінії, розташованої між колонками при
              мультиколонній верстці.
            </p>
          }
        />
      ),
    },
    {
      title: "column-rule-width",
      category: "CSS",
      textForSearch: "Ширина лінії між стовпцями.",
      jsx: (
        <TableTwoCol
          title={<h3>column-rule-width:</h3>}
          text={<p>Задає ширину лінії, намальованої між стовпцями.</p>}
        />
      ),
    },
    {
      title: "empty-cells",
      category: "CSS",
      textForSearch: "Відображення рамок для порожніх комірок таблиці.",
      jsx: (
        <TableTwoCol
          title={<h3>empty-cells:</h3>}
          text={
            <p>
              Визначає, чи відображатимуться межі та фон навколо
              <code>&lt;table&gt;</code> осередків, які не мають видимого
              вмісту.
            </p>
          }
        />
      ),
    },
    {
      title: "table-layout",
      category: "CSS",
      textForSearch: "Алгоритм розмітки таблиці.",
      jsx: (
        <TableTwoCol
          title={<h3>table-layout:</h3>}
          text={
            <p>
              Вказує алгоритм, який використовується для розмітки
              <code>&lt;table&gt;</code> осередків, рядків та стовпців.
            </p>
          }
        />
      ),
    },
  ];

  const filteredData = tableData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredData.length > 0 && (
        <Table id="css_table">
          <TableBody>
            <TableOneCol text={<h2>Таблиці.</h2>} />,
            {filteredData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
