import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function EditsUA({ searchTerm }: IMethodsProps) {
  const editsData = [
    {
      title: "Розмежувальні виправлення",
      category: "HTML",
      textForSearch: "Розмежувальні виправлення, <del>, <ins>.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>Ці елементи дозволяють вам відзначити певні частини тексту.</p>
            }
          />
        </>
      ),
    },
    {
      title: "<del>",
      category: "HTML",
      textForSearch: "<del>, видалений текст, del.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;del&gt; &lt;/del&gt;</h3>}
          text={<p>Представляє діапазон тексту, видаленого з документа.</p>}
        />
      ),
    },
    {
      title: "<ins>",
      category: "HTML",
      textForSearch: "<ins>, доданий текст, ins.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;ins&gt; &lt;/ins&gt;</h3>}
          text={
            <p>Являє собою діапазон тексту, який був доданий до документа.</p>
          }
        />
      ),
    },
  ];

  const filteredEditsData = editsData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredEditsData.length > 0 && (
        <Table id="html_edits">
          <TableBody>
            <TableOneCol text={<h2>Розмежувальні виправлення.</h2>} />
            {filteredEditsData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
