import React, { useState, useEffect, useRef } from "react";
import Container from "@mui/material/Container";
import TableContainer from "@mui/material/TableContainer";
import Button from "@mui/material/IconButton";
import Arrow from "../../core/Arrow";
import MenuJs from "./MenuJs.tsx";
import "./js.scss";
import VisibilityRU from "./VisibilityRU.tsx";
import VariablesRU from "./VariablesRU.tsx";
import OperatorsRU from "./OperatorsRU.tsx";
import CyclesRU from "./CyclesRU.tsx";
import NumberRU from "./NumberRU.tsx";
import StringRU from "./StringRU.tsx";
import ObjectRU from "./ObjectRU.tsx";
import ArrayRU from "./ArrayRU.tsx";
import FunctionRU from "./FunctionRU.tsx";
import RegularExpressionsRU from "./RegularExpressionsRU.tsx";
import SymbolRU from "./SymbolRU.tsx";
import DescriptorRU from "./DescriptorRU.tsx";
import ProtoRU from "./ProtoRU.tsx";
import ClassRU from "./ClassRU.tsx";
import MapRU from "./MapRU.tsx";
import SetRU from "./SetRU.tsx";
import TimeRU from "./TimeRU.tsx";
import PromiseRU from "./PromiseRU.tsx";
import AwaitRU from "./AwaitRU.tsx";
import ProxyRU from "./ProxyRU.tsx";
import AppBar from "../AppBar.tsx";

export default function JsRU() {
  const [isMenuInfoOpen, setIsMenuInfoOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const menuRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  const handleMenuInfoOpen = () => {
    setIsMenuInfoOpen(!isMenuInfoOpen);
  };

  const handleMenuInfoClose = () => {
    setIsMenuInfoOpen(false);
  };

  useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      if (
        isMenuInfoOpen &&
        menuRef.current &&
        !menuRef.current.contains(event.target as Node) &&
        buttonRef.current &&
        !buttonRef.current.contains(event.target as Node)
      ) {
        setIsMenuInfoOpen(false);
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);

    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
    };
  }, [isMenuInfoOpen]);

  const handleSearch = (term) => {
    setSearchTerm(term);
  };

  return (
    <>
      <AppBar
        onSearch={handleSearch}
        classLangUA={"buttonLanguages"}
        toUA={"/js/ua"}
        titleLangUA={"UA"}
        classLangRU={"buttonLanguages active"}
        toRU={"/js/ru"}
        titleLangRU={"RU"}
        toHome={"/home/ru"}
        toHtml={"/html/ru"}
        toCss={"/css/ru"}
        toScss={"/scss/ru"}
        toJS={"/js/ru"}
        toDom={"/dom/ru"}
        toBom={"/bom/ru"}
        toHttp={"/http/ru"}
        toReact={"/react/ru"}
        toRedux={"/redux/ru"}
        toTS={"/ts/ru"}
        toNext={"/next/ru"}
        nameHome={"Главная страница"}
        nameHtml={"HTML5"}
        nameCss={"CSS"}
        nameScss={"SCSS"}
        nameJS={"JavaScript"}
        nameDom={"DOM"}
        nameBom={"BOM"}
        nameHttp={"HTTP"}
        nameReact={"React"}
        nameRedux={"Redux"}
        nameTS={"TypeScript"}
        nameNext={"NextJS"}
      />
      <Container style={{ width: "100%", maxWidth: "none" }}>
        <Button
          id="menu-btnInfo"
          aria-label="open drawer"
          onClick={handleMenuInfoOpen}
          ref={buttonRef}
        >
          JavaScript
        </Button>
        {isMenuInfoOpen && (
          <div ref={menuRef}>
            <MenuJs
              sectionFirst={"Область видимости"}
              sectionSecond={"Переменные"}
              sectionThird={"Операторы"}
              sectionFourth={"Циклы"}
              sectionFifth={"Числа и Math"}
              sectionSixth={"Строки"}
              sectionSeventh={"Объекты"}
              sectionEighth={"Массивы"}
              sectionNinth={"Функции"}
              sectionTenth={"Регулярные выражения"}
              sectionEleventh={"Symbol"}
              sectionTwelfth={"Дескриптор свойства"}
              sectionThirteenth={"Прототип объекта"}
              sectionFourteenth={"Классы"}
              sectionFifteenth={"Map"}
              sectionSixteenth={"Set"}
              sectionSeventeenth={"Порядок обработки событий"}
              sectionEighteenth={"Promise"}
              sectionNineteenth={"Async/await"}
              sectionTwentieth={"Proxy"}
              onClose={handleMenuInfoClose}
            />
          </div>
        )}
        <TableContainer>
          <VisibilityRU searchTerm={searchTerm} />
          <VariablesRU searchTerm={searchTerm} />
          <OperatorsRU searchTerm={searchTerm} />
          <CyclesRU searchTerm={searchTerm} />
          <NumberRU searchTerm={searchTerm} />
          <StringRU searchTerm={searchTerm} />
          <ObjectRU searchTerm={searchTerm} />
          <ArrayRU searchTerm={searchTerm} />
          <FunctionRU searchTerm={searchTerm} />
          <RegularExpressionsRU searchTerm={searchTerm} />
          <SymbolRU searchTerm={searchTerm} />
          <DescriptorRU searchTerm={searchTerm} />
          <ProtoRU searchTerm={searchTerm} />
          <ClassRU searchTerm={searchTerm} />
          <MapRU searchTerm={searchTerm} />
          <SetRU searchTerm={searchTerm} />
          <TimeRU searchTerm={searchTerm} />
          <PromiseRU searchTerm={searchTerm} />
          <AwaitRU searchTerm={searchTerm} />
          <ProxyRU searchTerm={searchTerm} />
        </TableContainer>
        <footer className="footer">
          <a
            target="_blank"
            href="https://developer.mozilla.org/ru/docs/Web/JavaScript"
          >
            Документация JS
          </a>
          <a target="_blank" href="https://learn.javascript.ru/">
            Toturial JavaScript
          </a>
        </footer>
      </Container>
      <Arrow />
    </>
  );
}
