import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import ButtonExampleWithBtn from "../../core/ButtonExampleWithBtn.tsx";
import {
  classConst,
  classOneConst,
  classGetSetConst,
  classExtendsConst,
  classSuperConst,
  classStaticConst,
  classStatic2Const,
} from "./ClassConstPre.ts";
import {
  classOne,
  classGetSet,
  classExtends,
  classSuper,
  classStatic,
  classStatic2,
} from "./class.js";
import { IMethodsProps } from "../../types/interface.ts";

export default function ClassRU({ searchTerm }: IMethodsProps) {
  const tableData = [
    {
      title: "Классы",
      textForSearch:
        "Классы — это шаблон для создания объектов. Они инкапсулируют данные с кодом для работы с этими данными. Классы в JS построены на прототипах, но также имеют некоторый синтаксис и семантику, которые не используются в семантике классов ES5. Синтаксис классов выглядит так:",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Классы — это шаблон для создания объектов. Они инкапсулируют
                данные с кодом для работы с этими данными. Классы в JS построены
                на прототипах, но также имеют некоторый синтаксис и семантику,
                которые не используются в семантике классов ES5. Синтаксис
                классов выглядит так:
                <br />
                <pre>
                  <code>{classConst}</code>
                </pre>
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "Пример Class",
      textForSearch:
        "Создаём объект. Создаём конструктор с именем. Присваиваем имя. Запускаем",
      jsx: (
        <ButtonExampleWithBtn
          titleButtonExample={"Пример Class"}
          title={
            <p id="formated-text">
              <span>
                Создаём объект.
                <br />
                Создаём конструктор с именем.
                <br />
                Присваиваем имя. <br />
                Запускаем
                <br />
                <br />
              </span>
              <span id="jsClassOne"></span>
            </p>
          }
          text={
            <pre>
              <code>{classOneConst}</code>
            </pre>
          }
          onClick={classOne}
        />
      ),
    },
    {
      title: "Пример Get & Set",
      textForSearch:
        "Создаём объект. Создаём конструктор с именем. Присваиваем имя. Запускаем",
      jsx: (
        <ButtonExampleWithBtn
          titleButtonExample={"Пример Get & Set"}
          title={
            <p id="formated-text">
              <span>
                Создаём объект.
                <br />
                Создаём конструктор с именем.
                <br />
                Присваиваем имя. <br />
                Запускаем
                <br />
                <br />
              </span>
              <span id="jsClassGetSet"></span>
            </p>
          }
          text={
            <pre>
              <code>{classGetSetConst}</code>
            </pre>
          }
          onClick={classGetSet}
        />
      ),
    },
    {
      title: "Наследование классов",
      textForSearch:
        "Наследование – это создание новых «классов» на основе существующих. Механизм наследования позволяет определить базовый класс например Animal, в нём описать то, что свойственно всем животным, а затем на его основе построить другие, более конкретные: хищник, травоядный и т.п.",
      jsx: (
        <>
          <TableOneCol text={<h3>Наследование классов.</h3>} />
          <TableOneCol
            text={
              <p>
                Наследование – это создание новых «классов» на основе
                существующих. Механизм наследования позволяет определить базовый
                класс например Animal, в нём описать то, что свойственно всем
                животным, а затем на его основе построить другие, более
                конкретные: хищник, травоядный и т.п.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "extends",
      textForSearch: "Позволяет наследовать класс от другого класса.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>extends</h3>}
            text={<p>Позволяет наследовать класс от другого класса.</p>}
          />
        </>
      ),
    },
    {
      title: "Пример extends",
      textForSearch:
        "Создадим два класса Animal и Lion. Класс Animal содержит функции run(скорость) и type(тип животного). Класс Lion наследующий Animal содержит функцию family(семойство животного). Мы вызываем функции и передаем значения, присущие львам, в функции run и type.",
      jsx: (
        <ButtonExampleWithBtn
          titleButtonExample={"Пример extends"}
          title={
            <p id="formated-text">
              <span>
                Создадим два класса Animal и Lion. <br />
                Класс Animal содержит функции run(скорость) и type(тип
                животного). <br />
                Класс Lion наследующий Animal содержит функцию family(семейство
                животного).
              </span>
              <br />
              <span>
                Мы вызываем функции и передаем значения, присущие львам, в
                функции run и type.
              </span>
              <br />
              <br />
              <span id="jsClassExtends"></span>
            </p>
          }
          text={
            <pre>
              <code>{classExtendsConst}</code>
            </pre>
          }
          onClick={classExtends}
        />
      ),
    },
    {
      title: "super",
      textForSearch:
        "Способен вызвать родительский конструктор и применяется внутри текущего конструктора.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>super</h3>}
            text={
              <p>
                Способен вызвать родительский конструктор и применяется внутри
                текущего конструктора.
              </p>
            }
          />
          <ButtonExampleWithBtn
            titleButtonExample={"Пример super"}
            title={
              <p id="formated-text">
                <span id="jsClassSuper"></span>
              </p>
            }
            text={
              <pre>
                <code>{classSuperConst}</code>
              </pre>
            }
            onClick={classSuper}
          />
        </>
      ),
    },
    {
      title: "Статические свойства",
      textForSearch:
        "По определению статические методы привязаны к классу , а не к экземплярам этого класса. Поэтому статические методы полезны для определения вспомогательных или служебных методов.",
      jsx: (
        <>
          <TableOneCol text={<h3>Статические свойства.</h3>} />
          <TableOneCol
            text={
              <p>
                По определению статические методы привязаны к классу , а не к
                экземплярам этого класса. Поэтому статические методы полезны для
                определения вспомогательных или служебных методов.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "Пример static",
      textForSearch:
        "Вызывать статические классы надо напрямую через имя класса. className.staticName() или this.constructor.staticName().",
      jsx: (
        <ButtonExampleWithBtn
          titleButtonExample={"Пример static"}
          title={
            <p id="formated-text">
              <span>
                Вызывать статические классы надо напрямую через имя класса.
                <br />
                className.staticName() или this.constructor.staticName().
              </span>
              <br />
              <br />
              <span id="jsclassStatic"></span>
            </p>
          }
          text={
            <pre>
              <code>{classStaticConst}</code>
            </pre>
          }
          onClick={classStatic}
        />
      ),
    },
    {
      title: "Пример static 2",
      textForSearch: "",
      jsx: (
        <ButtonExampleWithBtn
          titleButtonExample={"Пример static 2"}
          title={
            <p id="formated-text">
              <span id="jsclassStatic2"></span>
            </p>
          }
          text={
            <pre>
              <code>{classStatic2Const}</code>
            </pre>
          }
          onClick={classStatic2}
        />
      ),
    },
  ];

  const filteredData = tableData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredData.length > 0 && (
        <Table id="js_class">
          <TableBody>
            <TableOneCol text={<h2>Классы.</h2>} />
            {filteredData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
