import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoEqualCol from "../../core/TableTwoEqualCol.tsx";
import {
  contentOne,
  contentTwo,
  contentThree,
  contentFour,
  contentFive,
} from "./ScssConstPre.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function ContentRU({ searchTerm }: IMethodsProps) {
  const scssContentData = [
    {
      title: "Блоки контенту в міксинах",
      category: "SCSS",
      textForSearch: "@content, @include.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Есть возможность передачи блока стилей в миксин, которые будут
                расположены среди стилей, подключаемых этим миксином. Или стили
                будут размещены вместо директив @content, расположенных внутри
                миксина. Это дает возможность создания абстракций, что зависят
                от конструкций селекторов или директив. Например:
              </p>
            }
          />
          <TableTwoEqualCol
            title={
              <p>
                <pre>
                  <code>{contentOne}</code>
                </pre>
              </p>
            }
            text={
              <p>
                <pre>
                  <code>{contentTwo}</code>
                </pre>
              </p>
            }
          />
          <TableOneCol
            text={
              <p>
                Блоки контента, передаваемые в миксин, вычисляются в той же
                области видимости, где определен этот блок, а не миксин. Это
                означает, что локальные переменные миксина не могут быть
                использованы в блоке передаваемого контента и переменные будут
                восприняты как глобальные:
              </p>
            }
          />
          <TableTwoEqualCol
            title={
              <p>
                <pre>
                  <code>{contentThree}</code>
                </pre>
              </p>
            }
            text={
              <p>
                <pre>
                  <code>{contentFour}</code>
                </pre>
              </p>
            }
          />
          <TableOneCol
            text={
              <p>
                Кроме того, это означает, что переменные и миксины, которые
                используются в задаваемых блоках, зависят от других стилей,
                вблизи которых блок объявлен:
              </p>
            }
          />
          <TableOneCol
            text={
              <p>
                <pre>
                  <code>{contentFive}</code>
                </pre>
              </p>
            }
          />
        </>
      ),
    },
  ];

  const filteredScssContentData = scssContentData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredScssContentData.length > 0 && (
        <Table id="scss_content">
          <TableBody>
            <TableOneCol text={<h3>Блоки содержания в миксинах.</h3>} />
            {filteredScssContentData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
