import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import { matches } from "./DomConstPre.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function DomFindElementsUA({ searchTerm }: IMethodsProps) {
  const tableData = [
    {
      title: ".getElementById(id)",
      category: "DOM",
      textForSearch: "Пошук елемента за ідентифікатором.",
      jsx: (
        <TableTwoCol
          title={<h3>.getElementById(id)</h3>}
          text={
            <p>
              Знаходить елемент за ідентифікатором елемента, що є статичним.
              <br />
              <code>document.getElementById(id)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".getElementsByName(name)",
      category: "DOM",
      textForSearch: "Пошук елементів за іменем.",
      jsx: (
        <TableTwoCol
          title={<h3>.getElementsByName(name)</h3>}
          text={
            <p>
              Знаходить елементи за ім'ям, є динамічним (живим).
              <br />
              <code>document.getElementsByName(name)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".getElementsByTagName(name)",
      category: "DOM",
      textForSearch: "Пошук елементів за іменем тегу.",
      jsx: (
        <TableTwoCol
          title={<h3>.getElementsByTagName(name)</h3>}
          text={
            <p>
              Знаходить елементи за ім'ям тегів. Здатний шукати всередині
              елементів та є динамічним (живим).
              <br />
              <code>document.getElementsByTagName(name)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".getElementsByClassName(name)",
      category: "DOM",
      textForSearch: "Пошук елементів за назвою класу.",
      jsx: (
        <TableTwoCol
          title={<h3>.getElementsByClassName(name)</h3>}
          text={
            <p>
              Знаходить елементи за назвою класу. Здатний шукати всередині
              елементів є динамічним (живим).
              <br />
              <code>document.getElementsByClassName(name)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".querySelectorAll(selector)",
      category: "DOM",
      textForSearch: "Пошук усіх елементів, що відповідають CSS-селектору.",
      jsx: (
        <TableTwoCol
          title={<h3>.querySelectorAll(selector)</h3>}
          text={
            <p>
              Знаходить елементи відповідного селектора CSS. Здатний шукати
              всередині елементів і є статичним.
              <br />
              <code>document.querySelectorAll(selector)</code>
              <br />
              Пошук за тегом першого рівня вкладеності:
              <code>document.querySelectorAll(selector &gt; selector)</code>
              <br />
              Пошук за кількома класами:
              <code>document.querySelectorAll(selector, selector)</code>
              <br />
              Пошук за вкладеними класами:
              <code>document.querySelectorAll(selector selector)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".querySelector(selector)",
      category: "DOM",
      textForSearch: "Пошук першого елемента, що відповідає CSS-селектору.",
      jsx: (
        <TableTwoCol
          title={<h3>.querySelector(selector)</h3>}
          text={
            <p>
              Знаходить перший елемент відповідному CSS селектору. Здатний
              шукати всередині елементів та є статичним.
              <br />
              <code>document.querySelector(selector)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".closest",
      category: "DOM",
      textForSearch: "Пошук найближчого предка.",
      jsx: (
        <TableTwoCol
          title={<h3>.closest</h3>}
          text={
            <p>
              Шукає найближчого предка, котрий відповідає CSS селектору.
              <br />
              <code>document.querySelector(selector).closest(selector)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".matches",
      category: "DOM",
      textForSearch: "Перевірка відповідності елемента CSS-селектору.",
      jsx: (
        <TableTwoCol
          title={<h3>.matches</h3>}
          text={
            <p>
              Нічого не шукає, а перевіряє, чи задовольняє елемент CSS
              селектору, повертає <b>true</b> чи <b>false</b>.
              <br />
              <pre>
                <code>{matches}</code>
              </pre>
            </p>
          }
        />
      ),
    },
  ];

  const filteredData = tableData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredData.length > 0 && (
        <Table id="dom_findElement">
          <TableBody>
            <TableOneCol text={<h3>Пошук елементів.</h3>} />
            {filteredData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
