import React from "react";
import "./../menuComponent.scss";
import { IMenuInfoProps } from "../../types/interface";

function MenuCss({
  sectionFirst,
  sectionSecond,
  sectionThird,
  sectionFourth,
  sectionFifth,
  sectionSixth,
  sectionSeventh,
  sectionEighth,
  sectionNinth,
  sectionTenth,
  sectionEleventh,
  sectionTwelfth,
  sectionThirteenth,
  sectionFourteenth,
  onClose,
}: IMenuInfoProps) {
  return (
    <div className="menu-container">
      <a className="dropdown-item" href="#scss_import" onClick={onClose}>
        {sectionFirst}
      </a>
      <a className="dropdown-item" href="#scss_media" onClick={onClose}>
        {sectionSecond}
      </a>
      <a className="dropdown-item" href="#scss_extend" onClick={onClose}>
        {sectionThird}
      </a>
      <a className="dropdown-item" href="#scss_at-root" onClick={onClose}>
        {sectionFourth}
      </a>
      <a className="dropdown-item" href="#scss_debug" onClick={onClose}>
        {sectionFifth}
      </a>
      <a className="dropdown-item" href="#scss_warn" onClick={onClose}>
        {sectionSixth}
      </a>
      <a className="dropdown-item" href="#scss_error" onClick={onClose}>
        {sectionSeventh}
      </a>
      <a className="dropdown-item" href="#scss_if" onClick={onClose}>
        {sectionEighth}
      </a>
      <a className="dropdown-item" href="#scss_for" onClick={onClose}>
        {sectionNinth}
      </a>
      <a className="dropdown-item" href="#scss_each" onClick={onClose}>
        {sectionTenth}
      </a>
      <a className="dropdown-item" href="#scss_while" onClick={onClose}>
        {sectionEleventh}
      </a>
      <a className="dropdown-item" href="#scss_mixin" onClick={onClose}>
        {sectionTwelfth}
      </a>
      <a className="dropdown-item" href="#scss_argument" onClick={onClose}>
        {sectionThirteenth}
      </a>
      <a className="dropdown-item" href="#scss_content" onClick={onClose}>
        {sectionFourteenth}
      </a>
    </div>
  );
}

export default MenuCss;
