import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import { error, warn, debug } from "./ScssConstPre.tsx";
import { IMethodsProps } from "../../types/interface.ts";

export default function OtherDirectiveUA({ searchTerm }: IMethodsProps) {
  const scssDebugData = [
    {
      title: "Директива @debug",
      category: "SCSS",
      textForSearch: "@debug",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Виводить значення функцій Sass засобами стандартного виведення
                помилок. Це корисно для налагодження функцій Sass, особливо для
                тих, що містять складну структуру даних.
              </p>
            }
          />
          <TableOneCol
            text={
              <p>
                <pre>
                  <code>{debug}</code>
                </pre>
              </p>
            }
          />
        </>
      ),
    },
  ];

  const scssWarnData = [
    {
      title: "Директива @warn",
      category: "SCSS",
      textForSearch: "@warn.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Виводить значення виразів Sass засобами стандартного виведення
                помилок. Ця директива корисна для бібліотек, яким потрібно
                попереджати користувачів про використання застарілих чи
                відновлених після незначних помилок міксинів. Є дві основні
                відмінності між **@warn** і **@debug**:
                <br />
                - Ви можете вимкнути відображення попереджень прапором `--quiet`
                в командному рядку або опцією `Sass: quiet`.
                <br />- Попередження буде виведено разом з уривком таблиці
                стилів, щоб користувач міг зрозуміти, де в коді потрібна його
                увага.
              </p>
            }
          />
          <TableOneCol
            text={
              <p>
                <pre>
                  <code>{warn}</code>
                </pre>
              </p>
            }
          />
        </>
      ),
    },
  ];

  const scssErrorData = [
    {
      title: "Директива @error",
      category: "SCSS",
      textForSearch: "@error",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Відображає значення виразів та функцій Sass як фатальну помилку,
                включаючи нормальну частину стека трасування. Ця директива є
                корисною для перевірки аргументів міксинів та функцій.
              </p>
            }
          />
          <TableOneCol
            text={
              <p>
                <pre>
                  <code>{error}</code>
                </pre>
              </p>
            }
          />
        </>
      ),
    },
  ];

  const filteredScssDebugData = scssDebugData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredScssWarnData = scssWarnData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredScssErrorData = scssErrorData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );
  return (
    <>
      {filteredScssDebugData.length > 0 && (
        <Table id="scss_debug">
          <TableBody>
            <TableOneCol text={<h3>@debug</h3>} />
            {filteredScssDebugData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}

      {filteredScssWarnData.length > 0 && (
        <Table id="scss_warn">
          <TableBody>
            <TableOneCol text={<h3>@warn</h3>} />
            {filteredScssWarnData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}

      {filteredScssErrorData.length > 0 && (
        <Table id="scss_error">
          <TableBody>
            <TableOneCol text={<h3>@error</h3>} />
            {filteredScssErrorData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
