import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "../../core/TableOneCol.tsx";
import TableTwoCol from "../../core/TableTwoCol.tsx";
import ButtonExampleWithBtn from "../../core/ButtonExampleWithBtn.tsx";
import { addElemets } from "./DomConstPre.tsx";
import { addElemetsFn } from "./DomFunc.js";
import { IMethodsProps } from "../../types/interface.ts";

export default function ElementsUA({ searchTerm }: IMethodsProps) {
  const tableCreate = [
    {
      title: ".append()",
      category: "DOM",
      textForSearch: "Додавання в кінець.",
      jsx: (
        <TableTwoCol
          title={<h3>.append()</h3>}
          text={<p>Додає вузли або рядки в кінець вибраного тега.</p>}
        />
      ),
    },
    {
      title: ".prepend()",
      category: "DOM",
      textForSearch: "Додавання на початок.",
      jsx: (
        <TableTwoCol
          title={<h3>.prepend()</h3>}
          text={<p>Вставляє вузли або рядки на початок вибраного тега.</p>}
        />
      ),
    },
    {
      title: ".before()",
      category: "DOM",
      textForSearch: "Вставка до елемента.",
      jsx: (
        <TableTwoCol
          title={<h3>.before()</h3>}
          text={<p>Вставляє вузли або рядки до вибраного тега.</p>}
        />
      ),
    },
    {
      title: ".after()",
      category: "DOM",
      textForSearch: "Вставка після елемента.",
      jsx: (
        <TableTwoCol
          title={<h3>.after()</h3>}
          text={<p>Вставляє вузли або рядки після вибраного тега.</p>}
        />
      ),
    },
    {
      title: ".replaceWith()",
      category: "DOM",
      textForSearch: "Заміна елемента.",
      jsx: (
        <TableTwoCol
          title={<h3>.replaceWith()</h3>}
          text={<p>Замінює вибраний тег заданими вузлами або рядками.</p>}
        />
      ),
    },
    {
      title: "Приклад додавання елементів",
      category: "DOM",
      textForSearch:
        "Приклад додавання, append, prepend, before, after, replaceWith.",
      jsx: (
        <ButtonExampleWithBtn
          titleButtonExample={"Приклад"}
          title={
            <p id="formated-text">
              <div className="list_ol">
                <ol id="list_ol">
                  <li>0</li>
                  <li>1</li>
                  <li>2</li>
                </ol>
              </div>
            </p>
          }
          text={
            <pre>
              <code>{addElemets}</code>
            </pre>
          }
          onClick={addElemetsFn}
        />
      ),
    },
  ];

  const tableCloneNode = [
    {
      title: ".cloneNode(deep)",
      category: "DOM",
      textForSearch: "Клонування з дочірніми елементами.",
      jsx: (
        <TableTwoCol
          title={<h3>.cloneNode(deep)</h3>}
          text={
            <p>
              Клонує елемент, якщо <b>deep == true</b>, то з усіма дочірніми
              елементами.
              <br />
              <code>element.cloneNode(deep)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".cloneNode(true)",
      category: "DOM",
      textForSearch: "Глибоке клонування.",
      jsx: (
        <TableTwoCol
          title={<h3>.cloneNode(true)</h3>}
          text={
            <p>
              Створює «глибокий» клон елемента – з усіма атрибутами та дочірніми
              елементами.
              <br />
              <code>element.cloneNode(true)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".cloneNode(false)",
      category: "DOM",
      textForSearch: "Поверхневе клонування.",
      jsx: (
        <TableTwoCol
          title={<h3>.cloneNode(false)</h3>}
          text={
            <p>
              Клон буде без дочірніх елементів.
              <br />
              <code>element.cloneNode(false)</code>
            </p>
          }
        />
      ),
    },
  ];

  const filteredCreate = tableCreate.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredCloneNode = tableCloneNode.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );
  return (
    <>
      {filteredCloneNode.length > 0 && (
        <Table id="dom_create">
          <TableBody>
            <TableOneCol text={<h3>Додавання та видалення елементів.</h3>} />
            {filteredCreate.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}

      {filteredCloneNode.length > 0 && (
        <Table id="dom_cloneNode">
          <TableBody>
            <TableOneCol text={<h3>Клонування елементів.</h3>} />
            {filteredCloneNode.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
